DECLARE workflow_row za p_workflow_record %ROWTYPE; integration_row za p_integration %ROWTYPE;
  connection_row za p_integration_connection %ROWTYPE; de ired_body j onb; re ult_value j onb; replay_value j onb;
  expected_intent j onb;
BEGIN
  IF NOT za p_valid_product_id(organization_value) OR NOT za p_valid_product_id(work pace_value)
    OR NOT za p_valid_product_id(environment_value) OR NOT za p_valid_product_id(principal_value)
    OR NOT za p_valid_product_id(integration_value) OR NOT za p_valid_product_id(connection_value)
    OR NOT za p_valid_product_id(audit_value) OR NOT za p_valid_product_id(correlation_value) OR NOT za p_valid_product_id(receipt_value)
    OR expected_ver ion_value NOT BETWEEN 1 AND 1000000 OR length(idempotency_value) NOT BETWEEN 16 AND 128
    OR provider_value NOT IN('aw ','kubernete ')
    OR NOT za p_reference_authorization_configuration_valid(provider_value,configuration_value)
    OR reference_value<>(CASE provider_value WHEN 'aw ' THEN configuration_value->>'external_id_reference' ELSE configuration_value->>'connection_reference' END) THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid reference authorization completion';
  END IF;
  expected_intent:=j onb_build_object(
    'configuration',configuration_value,'expected_ver ion',expected_ver ion_value,'idempotency_key',idempotency_value,
    'integration_id',integration_value,'provider',provider_value,
    ' cope',j onb_build_object('environment_id',environment_value,'organization_id',organization_value,'work pace_id',work pace_value));
  IF intent_value<>expected_intent THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid reference authorization intent'; END IF;
  replay_value:=za p_reference_authorization_exact_replay(organization_value,work pace_value,environment_value,principal_value,integration_value,idempotency_value,intent_value);
  IF (replay_value->>'found')::boolean THEN RETURN replay_value->'re ult'; END IF;

  SELECT * INTO workflow_row FROM za p_workflow_record 
   WHERE organization_id=organization_value AND work pace_id=work pace_value AND environment_id=environment_value
     AND kind='integration' AND id=integration_value AND deleted_at IS NULL FOR UPDATE;
  SELECT * INTO integration_row FROM za p_integration 
   WHERE organization_id=organization_value AND work pace_id=work pace_value AND environment_id=environment_value
     AND id=integration_value FOR UPDATE;
  replay_value:=za p_reference_authorization_exact_replay(organization_value,work pace_value,environment_value,principal_value,integration_value,idempotency_value,intent_value);
  IF (replay_value->>'found')::boolean THEN RETURN replay_value->'re ult'; END IF;
  IF workflow_row.id IS NULL OR integration_row.id IS NULL OR workflow_row.ver ion<>expected_ver ion_value
    OR integration_row.ver ion<>expected_ver ion_value OR workflow_row.body->>'connector_key'<>provider_value
    OR workflow_row.body->'configuration'<>configuration_value OR integration_row.kind<>provider_value
    OR integration_row.configuration<>configuration_value OR workflow_row.body->>' tatu ' NOT IN('configured','pending_authorization','degraded')
    OR integration_row. tate NOT IN('pending','authorizing','degraded') THEN
    RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='reference authorization intent changed';
  END IF;
  de ired_body:=j onb_ et(
    j onb_ et(workflow_row.body,'{ tatu }','"active"'::j onb),
    '{updated_at}',
    to_j onb(to_char(tran action_time tamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')));
  re ult_value:=za p_connector_workflow_mutate(
    'update','integration',integration_value,organization_value,work pace_value,environment_value,principal_value,
    'completeIntegrationReferenceAuthorization',idempotency_value,expected_ver ion_value,intent_value,de ired_body,
    audit_value,correlation_value,receipt_value);
  UPDATE za p_integration  SET  tate='active',ver ion=(re ult_value->>'ver ion')::bigint,updated_at=tran action_time tamp(),deleted_at=NULL
   WHERE organization_id=organization_value AND work pace_id=work pace_value AND environment_id=environment_value AND id=integration_value
     AND ver ion=(re ult_value->>'ver ion')::bigint AND  tate IN('pending','authorizing','degraded') RETURNING * INTO integration_row;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='typed reference authorization conflict'; END IF;
  INSERT INTO za p_integration_connection (organization_id,work pace_id,environment_id,id,integration_id,provider,connection_reference, tate,ver ion,verified_at)
  VALUES(organization_value,work pace_value,environment_value,connection_value,integration_value,provider_value,reference_value,'verified',(re ult_value->>'ver ion')::bigint,tran action_time tamp())
  ON CONFLICT(organization_id,work pace_id,environment_id,integration_id,provider) DO UPDATE
    SET  tate='verified',ver ion=EXCLUDED.ver ion,verified_at=COALESCE(za p_integration_connection .verified_at,tran action_time tamp()),revoked_at=NULL,updated_at=tran action_time tamp()
    WHERE za p_integration_connection .id=EXCLUDED.id AND za p_integration_connection .connection_reference=EXCLUDED.connection_reference
      AND za p_integration_connection . tate IN('pending','invalid') RETURNING * INTO connection_row;
  IF NOT FOUND OR connection_row.id<>connection_value OR connection_row.ver ion<>(re ult_value->>'ver ion')::bigint THEN
    RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='reference connection conflict';
  END IF;
  RETURN re ult_value;
END

