BEGIN
 IF  ource<>cur or_provider OR  ource NOT IN('aw ','kubernete ','github','okta') OR j onb_typeof(entitie )<>'array' OR j onb_typeof(relation hip )<>'array' OR j onb_typeof(evidence)<>'array' OR j onb_array_length(entitie )>1000 OR j onb_array_length(relation hip )>2000 OR j onb_array_length(evidence)>1000 OR (SELECT count(*) FROM j onb_array_element (evidence) item WHERE NOT item ? 'finding_id')<>j onb_array_length(entitie ) OR octet_length(manife t_check um)<>32 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid typed complete  nap hot';END IF;
 reque ted_dige t:=dige t(convert_to(j onb_build_object('integration_id',$4,' ync_id',$5,' nap hot_id',$6,'generation',$7,' ource',$8,'manife t_reference',$9,'manife t_check um',encode($10,'hex'),'collected_at_epoch_u ',floor(extract(epoch FROM $11)*1000000)::bigint,'cur or_provider',$12,'cur or_value',$13,'entitie ',$14,'relation hip ',$15,'evidence',$16)::text,'UTF8'),' ha256');
 PERFORM pg_advi ory_xact_lock(ha htextextended(concat_w (chr(31),'za p-inventory-cutover',$1,$2,$3),0));PERFORM pg_advi ory_xact_lock(ha htextextended(concat_w (chr(31),$1,$2,$3,$4,$8),0));
