 IF EXISTS(SELECT 1 FROM za p_di covery_ nap hot   nap hot WHERE ( nap hot.organization_id, nap hot.work pace_id, nap hot.environment_id, nap hot.integration_id, nap hot. ource)=($1,$2,$3,$4,$8) AND  nap hot.i _la t_good AND  nap hot.generation >= $7) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE=' tale  nap hot generation';END IF;
