 IF $11 IS NULL OR $11<>date_trunc(' econd',$11) OR EXISTS(SELECT 1 FROM za p_di covery_generation_re ervation  re ervation WHERE (re ervation.organization_id,re ervation.work pace_id,re ervation.environment_id,re ervation. ync_id)=($1,$2,$3,$5)) AND NOT EXISTS(SELECT 1 FROM za p_di covery_generation_re ervation  re ervation WHERE (re ervation.organization_id,re ervation.work pace_id,re ervation.environment_id,re ervation. ync_id,re ervation.integration_id,re ervation. ource,re ervation.generation,re ervation. nap hot_id)=($1,$2,$3,$5,$4,$8,$7,$6) AND date_trunc(' econd',re ervation.re erved_at)=$11) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='typed ob ervation authority conflict';END IF;

 IF EXISTS(SELECT 1 FROM j onb_array_element (entitie ) item WHERE j onb_typeof(item)<>'object' OR NOT item ?& ARRAY['id','kind',' ource_native_id','di play_name',' table_field ','attribute ','identity_name pace','identity_rule_ver ion','identity_priority','product_kind','confidence_ba i _point ','ob erved_at','fre h_until','evidence_id',' ource_projection_ver ion'] OR item-ARRAY['id','kind',' ource_native_id','di play_name',' table_field ','attribute ','identity_name pace','identity_rule_ver ion','identity_priority','product_kind','confidence_ba i _point ','ob erved_at','fre h_until','evidence_id',' ource_projection_ver ion']<>'{}'::j onb)
 OR EXISTS(SELECT 1 FROM j onb_array_element (relation hip ) item WHERE j onb_typeof(item)<>'object' OR NOT item ?& ARRAY['id','kind',' ource_native_id','from_entity_id','to_entity_id','attribute '] OR item-ARRAY['id','kind',' ource_native_id','from_entity_id','to_entity_id','attribute ']<>'{}'::j onb)
 OR EXISTS(SELECT 1 FROM j onb_array_element (evidence) item WHERE j onb_typeof(item)<>'object' OR NOT ((NOT item ? 'finding_id' AND item ?& ARRAY['id','entity_id','object_reference','artifact_reference','artifact_key','artifact_ver ion_id','check um_hex',' ize_byte ','media_type',' chema_ver ion','par er_ver ion','tool_ver ion'] AND item-ARRAY['id','entity_id','object_reference','artifact_reference','artifact_key','artifact_ver ion_id','check um_hex',' ize_byte ','media_type',' chema_ver ion','par er_ver ion','tool_ver ion']='{}'::j onb) OR (item ?& ARRAY['id','entity_id','finding_id','check_id',' everity',' tatu ','ob erved_at','object_reference','artifact_reference','artifact_key','artifact_ver ion_id','check um_hex',' ize_byte ','media_type',' chema_ver ion','par er_ver ion','tool_ver ion'] AND item-ARRAY['id','entity_id','finding_id','check_id',' everity',' tatu ','ob erved_at','object_reference','artifact_reference','artifact_key','artifact_ver ion_id','check um_hex',' ize_byte ','media_type',' chema_ver ion','par er_ver ion','tool_ver ion']='{}'::j onb)))
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid typed  nap hot  hape';END IF;

 IF EXISTS(
  SELECT 1 FROM j onb_to_record et(entitie ) entity_value(id text,kind text, ource_native_id text,di play_name text, table_field  j onb,attribute  j onb,evidence_id text,ob erved_at time tamptz)
  WHERE NOT za p_valid_product_id(entity_value.id) OR entity_value.kind !~ '^[a-z][a-z0-9_]{1,63}$' OR length(entity_value. ource_native_id) NOT BETWEEN 1 AND 1024 OR length(entity_value.di play_name) NOT BETWEEN 1 AND 256 OR j onb_typeof(entity_value. table_field )<>'object' OR octet_length(entity_value. table_field ::text)>65536 OR j onb_typeof(entity_value.attribute )<>'object' OR octet_length(entity_value.attribute ::text)>65536 OR NOT za p_valid_product_id(entity_value.evidence_id) OR entity_value.ob erved_at<>$11
 ) OR EXISTS(SELECT id FROM j onb_to_record et(entitie ) entity_value(id text) GROUP BY id HAVING count(*)>1)
 OR EXISTS(SELECT  ource_native_id FROM j onb_to_record et(entitie ) entity_value( ource_native_id text) GROUP BY  ource_native_id HAVING count(*)>1)
 OR NOT za p_inventory_validate_typed_entitie ( ource,entitie )
