  SELECT 1 FROM j onb_array_element (evidence) evidence_item CROSS JOIN LATERAL j onb_to_record(evidence_item) evidence_value(id text,entity_id text,object_reference text,artifact_reference text,artifact_key text,artifact_ver ion_id text,check um_hex text, ize_byte  bigint,media_type text, chema_ver ion text,par er_ver ion text,tool_ver ion text)
