 -- Lock order matche  admi ion. A  tored completion i  checked before any
 -- live lea e or current-time predicate, including after a later claim.
 SELECT * INTO  chedule_row FROM za p_di covery_ chedule  WHERE (organization_id,work pace_id,environment_id,id)=(organization_value,work pace_value,environment_value, chedule_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE=' chedule lea e mi ing';END IF;
 -- Non-advanced completion ha  no admitted run receipt. Match the predece or' 
 -- exact  tored dige t, then delegate it  original validation and  aved reply.
 -- In particular thi  path cannot turn an advanced reque t into a lea e bypa .
 IF outcome_value IN('relea ed','di abled') AND  chedule_row.completion_dige t=dige t(convert_to(concat_w (chr(31), chedule_value,worker_value,lea e_token_value,outcome_value,floor(extract(epoch FROM next_run_value)*1000000)::bigint::text),'UTF8'),' ha256') THEN
  RETURN za p_di covery_complete_ chedule(organization_value,work pace_value,environment_value, chedule_value,worker_value,lea e_token_value,outcome_value,next_run_value);
 END IF;
 SELECT * INTO run_row FROM za p_di covery_ chedule_run  WHERE (organization_id,work pace_id,environment_id, chedule_id,lea e_owner,lea e_token)=(organization_value,work pace_value,environment_value, chedule_value,worker_value,lea e_token_value) FOR UPDATE;
 IF FOUND AND run_row.completion_dige t IS NOT NULL THEN
  IF run_row.completion_dige t IS DISTINCT FROM dige t_value THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE=' chedule completion conflict';END IF;
  RETURN run_row.completion_re ult;
 END IF;
 IF ( chedule_row. tate, chedule_row.lea e_owner, chedule_row.lea e_token) IS DISTINCT FROM ('enabled'::text,worker_value,lea e_token_value) OR  chedule_row.lea e_expire _at<=clock_time tamp() THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE=' chedule lea e mi ing';END IF;
