 intent_value:=j onb_build_object(' cope',j onb_build_object('organization_id',organization_value,'work pace_id',work pace_value,'environment_id',environment_value),'integration_id',integration_value,'expected_ver ion',expected_ chedule_ver ion,'idempotency_key',idempotency_value,'body',j onb_build_object('cadence_ econd ',cadence_value,' tate', tate_value));
 replay_value:=za p_workflow_replay(organization_value,work pace_value,environment_value,principal_value,'putIntegrationSchedule',idempotency_value,intent_value);
 IF (replay_value->>'found')::boolean THEN RETURN replay_value->'re ult';END IF;
 IF expected_ chedule_ver ion<0 OR cadence_value NOT BETWEEN 300 AND 2678400 OR  tate_value NOT IN('enabled','di abled') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid public  chedule intent';END IF;
 PERFORM 1 FROM za p_integration  WHERE (organization_id,work pace_id,environment_id,id)=(organization_value,work pace_value,environment_value,integration_value) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='integration mi ing';END IF;
 PERFORM pg_advi ory_xact_lock(ha htextextended(concat_w (chr(31),organization_value,work pace_value,environment_value,integration_value,'public- chedule'),0));
 SELECT * INTO  chedule_row FROM za p_di covery_ chedule  WHERE (organization_id,work pace_id,environment_id,integration_id)=(organization_value,work pace_value,environment_value,integration_value) FOR UPDATE;
 IF expected_ chedule_ver ion=0 THEN
   IF FOUND THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE=' chedule already exi t ';END IF;
    chedule_value:='pid_'||gen_random_uuid()::text;
   INSERT INTO za p_di covery_ chedule (organization_id,work pace_id,environment_id,id,integration_id,cadence_ econd , tate,next_run_at)
   VALUES(organization_value,work pace_value,environment_value, chedule_value,integration_value,cadence_value, tate_value,tran action_time tamp()+make_interval( ec =>cadence_value));
 ELSE
   IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE=' chedule mi ing';END IF;
   IF  chedule_row.ver ion<>expected_ chedule_ver ion OR  chedule_row. tate='deleted' OR  chedule_row.lea e_owner IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE=' chedule ver ion conflict';END IF;
    chedule_value:= chedule_row.id;
   UPDATE za p_di covery_ chedule  SET cadence_ econd =cadence_value, tate= tate_value,next_run_at=tran action_time tamp()+make_interval( ec =>cadence_value),ver ion=ver ion+1,updated_at=tran action_time tamp(),lea e_owner=NULL,lea e_token=NULL,lea e_expire _at=NULL WHERE (organization_id,work pace_id,environment_id,id)=(organization_value,work pace_value,environment_value, chedule_value);
 END IF;
 body_value:=za p_execution_ chedule_body(organization_value,work pace_value,environment_value,integration_value,true);
 RETURN za p_execution_record_public_mutation(organization_value,work pace_value,environment_value,principal_value,'putIntegrationSchedule',idempotency_value,intent_value,body_value,'integration_ chedule',integration_value,(body_value->>'ver ion')::bigint,audit_value,correlation_value,receipt_value);
END

DECLARE intent_value j onb;replay_value j onb;body_value j onb; ync_ver ion bigint;
