 replay_value:=za p_workflow_replay(organization_value,work pace_value,environment_value,principal_value,' yncIntegration',idempotency_value,intent_value);
 IF (replay_value->>'found')::boolean THEN RETURN replay_value->'re ult';END IF;
 IF expected_integration_ver ion<1 OR octet_length(reque t_dige t_value)<>32 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid public  ync intent';END IF;
 PERFORM 1 FROM za p_integration  WHERE (organization_id,work pace_id,environment_id,id,ver ion)=(organization_value,work pace_value,environment_value,integration_value,expected_integration_ver ion) AND  tate IN('active','degraded') FOR UPDATE;
 IF NOT FOUND THEN IF EXISTS(SELECT 1 FROM za p_integration  WHERE (organization_id,work pace_id,environment_id,id)=(organization_value,work pace_value,environment_value,integration_value)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='integration ver ion conflict';ELSE RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='integration mi ing';END IF;END IF;
 PERFORM za p_execution_reque t_ ync(organization_value,work pace_value,environment_value,principal_value,integration_value, ync_value,job_value,outbox_value,idempotency_value,reque t_dige t_value,'manual',par er_value,tool_value);
 body_value:=za p_execution_ ync_body(organization_value,work pace_value,environment_value,integration_value, ync_value);
 SELECT ver ion INTO STRICT  ync_ver ion FROM za p_di covery_ ync  WHERE (organization_id,work pace_id,environment_id,id)=(organization_value,work pace_value,environment_value, ync_value);
 RETURN za p_execution_record_public_mutation(organization_value,work pace_value,environment_value,principal_value,' yncIntegration',idempotency_value,intent_value,body_value,'integration_ ync', ync_value, ync_ver ion,audit_value,correlation_value,receipt_value);
