DECLARE re pon e j onb;
BEGIN
 IF operation_value NOT IN(' yncIntegration','putIntegrationSchedule','deleteIntegrationSchedule') OR re ource_kind_value NOT IN('integration_ ync','integration_ chedule')
    OR NOT za p_valid_product_id(principal_value) OR NOT za p_valid_product_id(re ource_value) OR NOT za p_valid_product_id(audit_value)
    OR NOT za p_valid_product_id(correlation_value) OR (receipt_value<>'' AND NOT za p_valid_product_id(receipt_value)) OR length(idempotency_value) NOT BETWEEN 16 AND 128
    OR j onb_typeof(intent_value)<>'object' OR j onb_typeof(body_value)<>'object' OR ver ion_value<1 THEN
   RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid public execution mutation';
 END IF;
 re pon e:=j onb_build_object('body',body_value,'ver ion',ver ion_value,'audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value,'replayed',fal e);
 INSERT INTO za p_workflow_audit(organization_id,work pace_id,environment_id,audit_id,correlation_id,principal_id,operation,re ource_kind,re ource_id,re ource_ver ion)
 VALUES(organization_value,work pace_value,environment_value,audit_value,correlation_value,principal_value,operation_value,re ource_kind_value,re ource_value,ver ion_value);
 INSERT INTO za p_workflow_idempotency(organization_id,work pace_id,environment_id,principal_id,operation,idempotency_key,reque t_dige t,re pon e)
 VALUES(organization_value,work pace_value,environment_value,principal_value,operation_value,idempotency_value,dige t(convert_to(intent_value::text,'UTF8'),' ha256'),re pon e-'replayed');
 IF receipt_value<>'' THEN
   INSERT INTO za p_workflow_receipt (organization_id,work pace_id,environment_id,principal_id,receipt_id,operation,idempotency_key,intent,re ult,re ource_kind,re ource_id,re ource_ver ion,audit_id,correlation_id)
   VALUES(organization_value,work pace_value,environment_value,principal_value,receipt_value,operation_value,idempotency_value,intent_value,body_value,re ource_kind_value,re ource_value,ver ion_value,audit_value,correlation_value);
 END IF;
 RETURN re pon e;
END

DECLARE principal  text[]:=ARRAY[ cheduler_principal,di covery_principal,ri k_principal,graph_principal, earch_principal];authoritie  text[]:=ARRAY['za p_di covery_ cheduler','za p_di covery_worker','za p_projection_ri k_worker','za p_projection_graph_worker','za p_projection_ earch_worker'];index integer;role_value record;
BEGIN
 IF migration_principal<> e ion_u er OR cardinality(ARRAY(SELECT DISTINCT unne t(ARRAY[migration_principal, cheduler_principal,di covery_principal,ri k_principal,graph_principal, earch_principal])))<>6 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid execution principal '; END IF;
 PERFORM pg_advi ory_xact_lock(ha htextextended('za p-execution-principal-regi tration',0));
 FOR index IN 1..5 LOOP
   SELECT r.oid,r.rolcanlogin,r.rol uper,r.rolcreatedb,r.rolcreaterole,r.rolreplication,r.rolinherit,r.rolbypa rl  INTO role_value FROM pg_role  r WHERE r.rolname=principal [index];
   IF NOT FOUND OR NOT role_value.rolcanlogin OR role_value.rol uper OR role_value.rolcreatedb OR role_value.rolcreaterole OR role_value.rolreplication OR NOT role_value.rolinherit OR role_value.rolbypa rl  THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='un afe execution principal'; END IF;
   EXECUTE format('GRANT %I TO %I',authoritie [index],principal [index]);
   INSERT INTO za p_di covery_execution_principal (principal_name,authority_role) VALUES(principal [index],authoritie [index]) ON CONFLICT(principal_name) DO UPDATE SET authority_role=excluded.authority_role WHERE za p_di covery_execution_principal .authority_role=excluded.authority_role;
   IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='execution principal conflict'; END IF;
 END LOOP;
 RETURN true;
END

DECLARE  chedule_row za p_di covery_ chedule %ROWTYPE;re ult j onb;affected integer;
BEGIN
 IF NOT public.za p_execution_principal_ready('za p_di covery_ cheduler') AND NOT EXISTS(SELECT 1 FROM public.za p_di covery_principal_binding  WHERE principal_name= e ion_u er AND authority_role='za p_di covery_authority') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE=' cheduler authority denied';END IF;
 SELECT * INTO  chedule_row FROM za p_di covery_ chedule  WHERE (organization_id,work pace_id,environment_id,id,integration_id, tate,lea e_owner,lea e_token)=(organization_value,work pace_value,environment_value, chedule_value,integration_value,'enabled',worker_value,lea e_token_value) FOR UPDATE;
 IF NOT FOUND OR  chedule_row.lea e_expire _at<=clock_time tamp() THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE=' chedule lea e mi ing';END IF;
 re ult:=za p_execution_reque t_ ync(organization_value,work pace_value,environment_value,principal_value,integration_value, ync_value,job_value,outbox_value,idempotency_value,reque t_dige t_value,' chedule',par er_value,tool_value);
 IF (re ult->>' ync_id',re ult->>'job_id',re ult->>'outbox_id') IS DISTINCT FROM ( ync_value,job_value,outbox_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE=' chedule run conflict';END IF;
 INSERT INTO za p_di covery_ chedule_run (organization_id,work pace_id,environment_id, chedule_id, ync_id,job_id,lea e_owner,lea e_token,reque t_dige t, cheduled_for)
 VALUES(organization_value,work pace_value,environment_value, chedule_value, ync_value,job_value,worker_value,lea e_token_value,reque t_dige t_value, chedule_row.next_run_at)
 ON CONFLICT ON CONSTRAINT za p_di covery_ chedule_run _occurrence_key DO NOTHING;
 GET DIAGNOSTICS affected=ROW_COUNT;
 IF affected=0 THEN
  IF NOT EXISTS(SELECT 1 FROM za p_di covery_ chedule_run  r WHERE (r.organization_id,r.work pace_id,r.environment_id,r. chedule_id,r. cheduled_for,r. ync_id,r.job_id,r.reque t_dige t,r.lea e_owner,r.lea e_token)=(organization_value,work pace_value,environment_value, chedule_value, chedule_row.next_run_at, ync_value,job_value,reque t_dige t_value,worker_value,lea e_token_value) AND r.completed_at IS NULL AND r.completion_dige t IS NULL) THEN
   UPDATE za p_di covery_ chedule_run  r SET lea e_owner=worker_value,lea e_token=lea e_token_value,rebind_generation=r.rebind_generation+1
   WHERE (r.organization_id,r.work pace_id,r.environment_id,r. chedule_id,r. cheduled_for,r. ync_id,r.job_id,r.reque t_dige t)=(organization_value,work pace_value,environment_value, chedule_value, chedule_row.next_run_at, ync_value,job_value,reque t_dige t_value) AND r.completed_at IS NULL AND r.completion_dige t IS NULL AND (r.lea e_owner,r.lea e_token) IS DISTINCT FROM (worker_value,lea e_token_value);
   GET DIAGNOSTICS affected=ROW_COUNT;
   IF affected<>1 THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE=' chedule run conflict';END IF;
  END IF;
 END IF;
 IF  chedule_row.lea e_expire _at<=clock_time tamp() THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE=' chedule lea e mi ing';END IF;
 RETURN re ult;
END

DECLARE integration_row za p_integration %ROWTYPE;connection_row za p_integration_connection %ROWTYPE; ubject_row za p_di covery_connection_ ubject %ROWTYPE;re ult j onb;authority_row za p_di covery_job_authoritie %ROWTYPE;actual_ ync text;actual_job text;prior_ ync boolean;
BEGIN
 IF NOT pg_ha _role( e ion_u er,'za p_di covery_api','MEMBER') AND NOT pg_ha _role( e ion_u er,'za p_di covery_ cheduler','MEMBER') AND NOT pg_ha _role( e ion_u er,'za p_di covery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE=' ync authority denied';END IF;
 SELECT * INTO integration_row FROM za p_integration  WHERE (organization_id,work pace_id,environment_id,id)=(organization_value,work pace_value,environment_value,integration_value) AND  tate IN('active','degraded') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='integration mi ing';END IF;
 SELECT * INTO STRICT connection_row FROM za p_integration_connection  WHERE (organization_id,work pace_id,environment_id,integration_id,provider, tate)=(organization_value,work pace_value,environment_value,integration_value,integration_row.kind,'verified') FOR SHARE;
 SELECT * INTO STRICT  ubject_row FROM za p_di covery_connection_ ubject  WHERE (organization_id,work pace_id,environment_id,integration_id,connection_id,provider,connection_ver ion,configuration_dige t)=(organization_value,work pace_value,environment_value,integration_value,connection_row.id,integration_row.kind,connection_row.ver ion,dige t(convert_to(integration_row.configuration::text,'UTF8'),' ha256')) FOR SHARE;
 prior_ ync:=EXISTS(SELECT 1 FROM za p_di covery_ ync  WHERE (organization_id,work pace_id,environment_id,integration_id,idempotency_key)=(organization_value,work pace_value,environment_value,integration_value,idempotency_value));
 re ult:=za p_di covery_reque t_ ync(organization_value,work pace_value,environment_value,principal_value,integration_value, ync_value,job_value,outbox_value,idempotency_value,reque t_dige t_value,trigger_value,par er_value,tool_value);
 actual_ ync:=re ult->>' ync_id';actual_job:=re ult->>'job_id';
 INSERT INTO za p_di covery_job_authoritie (organization_id,work pace_id,environment_id,job_id, ync_id,integration_id,connection_id,provider,integration_ver ion,connection_ver ion,configuration,configuration_dige t, ubject_kind, ubject_id,reque t_dige t)
 VALUES(organization_value,work pace_value,environment_value,actual_job,actual_ ync,integration_value,connection_row.id,integration_row.kind,integration_row.ver ion,connection_row.ver ion,integration_row.configuration,dige t(convert_to(integration_row.configuration::text,'UTF8'),' ha256'), ubject_row. ubject_kind, ubject_row. ubject_id,reque t_dige t_value) ON CONFLICT(organization_id,work pace_id,environment_id,job_id) DO NOTHING;
 SELECT * INTO STRICT authority_row FROM za p_di covery_job_authoritie  WHERE (organization_id,work pace_id,environment_id,job_id)=(organization_value,work pace_value,environment_value,actual_job);
 IF (authority_row. ync_id,authority_row.integration_id,authority_row.connection_id,authority_row.provider,authority_row.integration_ver ion,authority_row.connection_ver ion,authority_row.configuration,authority_row.configuration_dige t,authority_row. ubject_kind,authority_row. ubject_id,authority_row.reque t_dige t)<>(actual_ ync,integration_value,connection_row.id,integration_row.kind,integration_row.ver ion,connection_row.ver ion,integration_row.configuration,dige t(convert_to(integration_row.configuration::text,'UTF8'),' ha256'), ubject_row. ubject_kind, ubject_row. ubject_id,reque t_dige t_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE=' ync authority conflict';END IF;
 IF NOT prior_ ync THEN PERFORM za p_execution_bump_fre hne (organization_value,work pace_value,environment_value,integration_value);END IF;
 RETURN re ult;
END

DECLARE re ult j onb;remaining_count integer;
BEGIN
 IF topic_value<>'di covery-job ' OR error_code_value<>'queue_publi h_unknown' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid execution outbox retry';END IF;
 IF NOT pg_ha _role( e ion_u er,'za p_outbox_worker','MEMBER') AND NOT pg_ha _role( e ion_u er,'za p_di covery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='outbox authority denied';END IF;
 IF NOT EXISTS(SELECT 1 FROM za p_di covery_outbox WHERE (organization_id,work pace_id,environment_id,id,topic)=(organization_value,work pace_value,environment_value,outbox_value,topic_value)) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='outbox topic lea e mi ing';END IF;
 re ult:=za p_di covery_retry_outbox(organization_value,work pace_value,environment_value,outbox_value,worker_value,lea e_token_value,retry_after_ econd ,error_code_value);
 SELECT count(*) INTO remaining_count FROM za p_di covery_outbox WHERE topic=topic_value AND  tate='lea ed' AND lea e_owner=worker_value AND lea e_token=lea e_token_value AND lea e_expire _at>tran action_time tamp();
 RETURN re ult||j onb_build_object('remaining_count',remaining_count);
END

DECLARE re pon e j onb;
BEGIN
 SELECT j onb_build_object(
   'id', ync.id,'integration_id', ync.integration_id,'trigger_kind', ync.trigger_kind,' tatu ', ync. tate,'attempt', ync.attempt,
   'reque ted_at',to_char( ync.reque ted_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
   ' tarted_at',CASE WHEN  ync. tarted_at IS NULL THEN NULL ELSE to_char( ync. tarted_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END,
   'completed_at',CASE WHEN  ync.completed_at IS NULL THEN NULL ELSE to_char( ync.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END,
   'di covered_count', ync.di covered_count,'changed_count', ync.changed_count,'removed_count', ync.removed_count,' nap hot_id', ync. nap hot_id,
   'la t_error_code', ync.la t_error_code,
   'retry_at',CASE WHEN  ync. tate='queued' AND  ync.attempt>0 THEN (SELECT to_char(job.available_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') FROM za p_di covery_job  job WHERE (job.organization_id,job.work pace_id,job.environment_id,job.kind,job.authority_id)=( ync.organization_id, ync.work pace_id, ync.environment_id,'di covery', ync.id)) ELSE NULL END
 ) INTO re pon e
 FROM za p_di covery_ ync   ync
 WHERE ( ync.organization_id, ync.work pace_id, ync.environment_id, ync.integration_id, ync.id)=(organization_value,work pace_value,environment_value,integration_value, ync_value);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE=' ync mi ing';END IF;
 RETURN re pon e;
