DECLARE job_row za p_di covery_job %ROWTYPE;input_row za p_di covery_ nap hot_input %ROWTYPE;terminal_ tate text;
BEGIN
 SELECT * INTO job_row FROM za p_di covery_job  WHERE (organization_id,work pace_id,environment_id,id,kind, tate)=(organization_value,work pace_value,environment_value,job_value,'di covery','lea ed') AND attempt>=5 AND lea e_expire _at<=tran action_time tamp() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='exhau ted di covery job mi ing';END IF;
 SELECT input.* INTO input_row FROM za p_di covery_job_authoritie  authority JOIN za p_di covery_generation_re ervation  re ervation ON (re ervation.organization_id,re ervation.work pace_id,re ervation.environment_id,re ervation. ync_id,re ervation.integration_id,re ervation. ource)=(authority.organization_id,authority.work pace_id,authority.environment_id,authority. ync_id,authority.integration_id,authority.provider) JOIN za p_di covery_ nap hot_input  input ON (input.organization_id,input.work pace_id,input.environment_id,input. nap hot_id,input.integration_id,input. ource,input.generation)=(re ervation.organization_id,re ervation.work pace_id,re ervation.environment_id,re ervation. nap hot_id,re ervation.integration_id,re ervation. ource,re ervation.generation) JOIN za p_di covery_ nap hot   nap hot ON ( nap hot.organization_id, nap hot.work pace_id, nap hot.environment_id, nap hot.id, nap hot. tate)=(input.organization_id,input.work pace_id,input.environment_id,input. nap hot_id,'complete') JOIN za p_di covery_ ync   ync ON ( ync.organization_id, ync.work pace_id, ync.environment_id, ync.id, ync.integration_id, ync. tate, ync. nap hot_id)=(authority.organization_id,authority.work pace_id,authority.environment_id,authority. ync_id,authority.integration_id,' ucceeded',input. nap hot_id) WHERE (authority.organization_id,authority.work pace_id,authority.environment_id,authority.job_id)=(organization_value,work pace_value,environment_value,job_value);
 terminal_ tate:=CASE WHEN FOUND THEN ' ucceeded' ELSE 'failed' END;
 UPDATE za p_di covery_job  SET  tate=terminal_ tate,re ult_dige t=CASE WHEN terminal_ tate=' ucceeded' THEN input_row.candidate_dige t ELSE re ult_dige t END,la t_error=CASE WHEN terminal_ tate='failed' THEN COALESCE(la t_error,'lea e expired after maximum attempt ') ELSE NULL END,completed_at=tran action_time tamp(),lea e_owner=NULL,lea e_token=NULL,lea e_expire _at=NULL,updated_at=tran action_time tamp() WHERE (organization_id,work pace_id,environment_id,id)=(organization_value,work pace_value,environment_value,job_value);
 UPDATE za p_di covery_ ync  SET  tate=terminal_ tate,attempt=job_row.attempt,la t_error=CASE WHEN terminal_ tate='failed' THEN COALESCE(la t_error,'lea e expired after maximum attempt ') ELSE NULL END,la t_error_code=CASE WHEN terminal_ tate='failed' THEN COALESCE(la t_error_code,'terminal') ELSE NULL END,completed_at=COALESCE(completed_at,tran action_time tamp()) WHERE (organization_id,work pace_id,environment_id,id)=(organization_value,work pace_value,environment_value,job_row.authority_id) AND ( tate IN('queued','running') OR terminal_ tate=' ucceeded' AND  tate=' ucceeded');
 RETURN j onb_build_object('id',job_value,' tate',terminal_ tate,'attempt',job_row.attempt,'completed_at',tran action_time tamp());
END

DECLARE
    reque ted_intent j onb;
    dige t_value bytea;
    prior_dige t bytea;
    prior_re pon e j onb;
    re ult_ver ion bigint;
    re ult_body j onb;
BEGIN
    LOCK TABLE "public"."za p_ri k_finding ", "public"."za p_workflow_idempotency", "public"."za p_workflow_audit", "public"."za p_workflow_receipt " IN ROW EXCLUSIVE MODE;
    PERFORM public.za p_audit_export _require_ready();
    IF NOT EXISTS (SELECT 1 FROM "public"."za p_ chema_ver ion " relea e JOIN "public"."za p_ chema_metadata" marker ON marker."key"='production_core_ chema' AND marker."value"='production-recovery-v1' WHERE relea e."ver ion"=27 AND relea e."name"='production_recovery' AND NOT EXISTS (SELECT 1 FROM "public"."za p_ chema_ver ion " later WHERE later."ver ion">60)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='ri k projection relea e unavailable';
    END IF;
    IF reque ted_operation NOT IN ('updateFinding','acceptFindingRi k') OR expected_ver ion<1
       OR length(reque ted_idempotency_key) NOT BETWEEN 16 AND 128
       OR reque ted_finding_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR reque ted_principal_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR reque ted_operation='updateFinding' AND (reque ted_ tatu  NOT IN ('open','under_review','re olved') OR reque ted_rea on IS NOT NULL)
       OR reque ted_operation='acceptFindingRi k' AND (reque ted_ tatu <>'accepted' OR length(reque ted_rea on) NOT BETWEEN 1 AND 512) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid ri k mutation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "public"."za p_ri k_finding " AS candidate WHERE "organization_id"=reque ted_organization_id AND "work pace_id"=reque ted_work pace_id AND "environment_id"=reque ted_environment_id AND "id"=reque ted_finding_id AND "public"."za p_ri k_finding_vi ible"(candidate)) THEN
        RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='ri k finding mi ing';
    END IF;
    reque ted_intent := j onb_build_object('re ource_id',reque ted_finding_id,'expected_ver ion',expected_ver ion,'body',CASE WHEN reque ted_operation='updateFinding' THEN j onb_build_object(' tatu ',reque ted_ tatu ) ELSE j onb_build_object('rea on',reque ted_rea on) END);
    PERFORM pg_advi ory_xact_lock(ha htextextended(concat_w (chr(31),reque ted_organization_id,reque ted_work pace_id,reque ted_environment_id,reque ted_principal_id,reque ted_operation,reque ted_idempotency_key),0));
    dige t_value := dige t(convert_to(reque ted_intent::text,'UTF8'),' ha256');
    SELECT "reque t_dige t","re pon e" INTO prior_dige t,prior_re pon e FROM "public"."za p_workflow_idempotency"
     WHERE "organization_id"=reque ted_organization_id AND "work pace_id"=reque ted_work pace_id AND "environment_id"=reque ted_environment_id
       AND "principal_id"=reque ted_principal_id AND "operation"=reque ted_operation AND "idempotency_key"=reque ted_idempotency_key;
    IF FOUND THEN
        IF prior_dige t<>dige t_value THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='idempotency conflict'; END IF;
        PERFORM public.za p_audit_export _require_ready(); RETURN prior_re pon e||j onb_build_object('replayed',true);
    END IF;
    UPDATE "public"."za p_ri k_finding " AS candidate SET " tatu "=reque ted_ tatu ,"acceptance_rea on"=CASE WHEN reque ted_operation='acceptFindingRi k' THEN reque ted_rea on ELSE NULL END,"ver ion"="ver ion"+1,"updated_at"=tran action_time tamp()
     WHERE "organization_id"=reque ted_organization_id AND "work pace_id"=reque ted_work pace_id AND "environment_id"=reque ted_environment_id AND "id"=reque ted_finding_id AND "ver ion"=expected_ver ion AND "public"."za p_ri k_finding_vi ible"(candidate)
     RETURNING "ver ion" INTO re ult_ver ion;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='ri k finding ver ion conflict'; END IF;
    re ult_body := "public"."za p_ri k_finding_get"(reque ted_finding_id,reque ted_organization_id,reque ted_work pace_id,reque ted_environment_id);
    prior_re pon e := j onb_build_object('body',re ult_body,'ver ion',re ult_ver ion,'audit_id',reque ted_audit_id,'correlation_id',reque ted_correlation_id,'replayed',fal e);
    IF reque ted_receipt_id IS NOT NULL THEN prior_re pon e:=prior_re pon e||j onb_build_object('receipt_id',reque ted_receipt_id); END IF;
    INSERT INTO "public"."za p_workflow_audit" ("organization_id","work pace_id","environment_id","audit_id","correlation_id","principal_id","operation","re ource_kind","re ource_id","re ource_ver ion") VALUES (reque ted_organization_id,reque ted_work pace_id,reque ted_environment_id,reque ted_audit_id,reque ted_correlation_id,reque ted_principal_id,reque ted_operation,'finding',reque ted_finding_id,re ult_ver ion);
    INSERT INTO "public"."za p_workflow_idempotency" ("organization_id","work pace_id","environment_id","principal_id","operation","idempotency_key","reque t_dige t","re pon e","receipt_ emantic ") VALUES (reque ted_organization_id,reque ted_work pace_id,reque ted_environment_id,reque ted_principal_id,reque ted_operation,reque ted_idempotency_key,dige t_value,prior_re pon e-'replayed',CASE WHEN reque ted_receipt_id IS NULL THEN 'receiptle _incompatible' ELSE 'receipt_backed' END);
    IF reque ted_receipt_id IS NOT NULL THEN
        INSERT INTO "public"."za p_workflow_receipt " ("organization_id","work pace_id","environment_id","principal_id","receipt_id","operation","idempotency_key","intent","re ult","re ource_kind","re ource_id","re ource_ver ion","audit_id","correlation_id") VALUES (reque ted_organization_id,reque ted_work pace_id,reque ted_environment_id,reque ted_principal_id,reque ted_receipt_id,reque ted_operation,reque ted_idempotency_key,reque ted_intent,re ult_body,'finding',reque ted_finding_id,re ult_ver ion,reque ted_audit_id,reque ted_correlation_id);
    END IF;
    PERFORM public.za p_audit_export _require_ready(); RETURN prior_re pon e;
END;

DECLARE
    mutation_re pon e j onb;
    exi ting_receipt_id text;
BEGIN
    LOCK TABLE "public"."za p_workflow_idempotency" IN ROW EXCLUSIVE MODE;
    PERFORM public.za p_audit_export _require_ready();
    IF NOT EXISTS (
        SELECT 1
          FROM "public"."za p_ chema_ver ion " AS relea e
          JOIN "public"."za p_ chema_metadata" AS  chema_marker
            ON  chema_marker."key" = 'production_core_ chema'
           AND  chema_marker."value" = 'production-recovery-v1'
         WHERE relea e."ver ion" = 27
           AND relea e."name" = 'production_recovery'
           AND NOT EXISTS (
               SELECT 1 FROM "public"."za p_ chema_ver ion " AS later_relea e
                WHERE later_relea e."ver ion" > 60
           )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance relea e unavailable';
    END IF;
    IF reque ted_receipt_id IS NOT NULL AND reque ted_receipt_id <> '' AND length(reque ted_receipt_id) > 128 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'invalid workflow receipt';
    END IF;
    mutation_re pon e := "public"."za p_workflow_mutate_v3"(
        mutation, reque ted_kind, reque ted_id,
        reque ted_organization_id, reque ted_work pace_id, reque ted_environment_id,
        reque ted_principal_id, reque ted_operation, reque ted_idempotency_key,
        expected_ver ion, reque ted_intent, reque ted_body, reque ted_audit_id, reque ted_correlation_id
    );
    exi ting_receipt_id := mutation_re pon e ->> 'receipt_id';
    IF exi ting_receipt_id IS NOT NULL THEN
        PERFORM public.za p_audit_export _require_ready(); RETURN mutation_re pon e;
    END IF;
    IF reque ted_receipt_id IS NULL OR reque ted_receipt_id = '' THEN
        UPDATE "public"."za p_workflow_idempotency"
           SET "receipt_ emantic " = 'receiptle _incompatible'
         WHERE "organization_id" = reque ted_organization_id AND "work pace_id" = reque ted_work pace_id
           AND "environment_id" = reque ted_environment_id AND "principal_id" = reque ted_principal_id
           AND "operation" = reque ted_operation AND "idempotency_key" = reque ted_idempotency_key
           AND NULLIF("re pon e" ->> 'receipt_id', '') IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
        END IF;
        PERFORM public.za p_audit_export _require_ready(); RETURN mutation_re pon e;
    END IF;
    INSERT INTO "public"."za p_workflow_receipt " (
        "organization_id", "work pace_id", "environment_id", "principal_id", "receipt_id",
        "operation", "idempotency_key", "intent", "re ult", "re ource_kind", "re ource_id",
        "re ource_ver ion", "audit_id", "correlation_id"
    ) VALUES (
        reque ted_organization_id, reque ted_work pace_id, reque ted_environment_id, reque ted_principal_id, reque ted_receipt_id,
        reque ted_operation, reque ted_idempotency_key, reque ted_intent, mutation_re pon e -> 'body', reque ted_kind, reque ted_id,
        (mutation_re pon e ->> 'ver ion')::bigint, mutation_re pon e ->> 'audit_id', mutation_re pon e ->> 'correlation_id'
    );
    mutation_re pon e := mutation_re pon e || j onb_build_object('receipt_id', reque ted_receipt_id);
    UPDATE "public"."za p_workflow_idempotency"
       SET "re pon e" = mutation_re pon e - 'replayed',
           "receipt_ emantic " = 'receipt_backed'
     WHERE "organization_id" = reque ted_organization_id AND "work pace_id" = reque ted_work pace_id
       AND "environment_id" = reque ted_environment_id AND "principal_id" = reque ted_principal_id
       AND "operation" = reque ted_operation AND "idempotency_key" = reque ted_idempotency_key;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
    END IF;
    PERFORM public.za p_audit_export _require_ready(); RETURN mutation_re pon e;
END;

