CREATE OR REPLACE FUNCTION public.zasp_runtime_claim_stage_precision_compatible(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer, expected_stage text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE stage_value text;authority_value text;result_value jsonb;prior_capability text;
BEGIN
 stage_value:=zasp_runtime_stage_for_session();
 IF worker_value IS NULL OR lease_token_value IS NULL OR lease_seconds IS NULL OR claim_limit IS NULL OR expected_stage IS NULL OR stage_value IS DISTINCT FROM expected_stage THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime routing capability rejected';END IF;
 authority_value:=CASE stage_value WHEN 'archive' THEN 'zasp_runtime_archive_worker' WHEN 'index' THEN 'zasp_runtime_index_worker' WHEN 'correlate' THEN 'zasp_runtime_correlation_worker' WHEN 'project' THEN 'zasp_runtime_projection_worker' WHEN 'complete' THEN 'zasp_runtime_coordinator' END;
 IF stage_value IS NULL OR NOT zasp_runtime_principal_ready(authority_value) OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime stage authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp-runtime-stage-claim:'||stage_value,0));
 prior_capability:=COALESCE(current_setting('zasp.runtime_precision_claim_version',true),'');
 PERFORM set_config('zasp.runtime_precision_claim_version',CASE stage_value WHEN 'archive' THEN 'runtime-archive-v2' WHEN 'index' THEN 'runtime-index-v2' WHEN 'correlate' THEN 'runtime-correlation-v4' WHEN 'project' THEN 'runtime-projection-v3' WHEN 'complete' THEN 'runtime-complete-v3' END,true);
 IF NOT COALESCE(zasp_production_runtime_precision_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime precision authority unavailable';END IF;
 WITH exhausted AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='failed',last_error_class='exhausted',completed_at=transaction_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_heartbeat_at=NULL,
   completion_digest=digest(convert_to(concat_ws(chr(31),stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation::text,stage_row.stage,stage_row.attempt::text,'exhausted'),'UTF8'),'sha256'),
   completion_result=jsonb_build_object('batch_id',stage_row.batch_id,'generation',stage_row.batch_generation,'stage',stage_row.stage,'state','failed','attempt',stage_row.attempt,'error_class','exhausted')
  WHERE stage_row.stage=stage_value AND (CASE stage_value WHEN 'archive' THEN stage_row.implementation_version IN('runtime-archive-v1','runtime-archive-v2') WHEN 'index' THEN stage_row.implementation_version IN('runtime-index-v1','runtime-index-v2') WHEN 'correlate' THEN stage_row.implementation_version IN('runtime-correlation-v1','runtime-correlation-v2','runtime-correlation-v3','runtime-correlation-v4') WHEN 'project' THEN stage_row.implementation_version IN('runtime-projection-v1','runtime-projection-v2','runtime-projection-v3') WHEN 'complete' THEN stage_row.implementation_version IN('runtime-complete-v1','runtime-complete-v2','runtime-complete-v3') ELSE false END) AND stage_row.attempt>=100 AND stage_row.state IN('pending','retryable','leased') AND (stage_row.state<>'leased' OR stage_row.lease_expires_at<=transaction_timestamp())
  RETURNING stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.completion_digest,stage_row.completion_result
 ),failed_batches AS (
  UPDATE zasp_runtime_batch_authorities authority_row SET state='failed',completed_at=transaction_timestamp(),completion_digest=exhausted.completion_digest,completion_result=exhausted.completion_result
  FROM exhausted WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(exhausted.organization_id,exhausted.workspace_id,exhausted.environment_id,exhausted.batch_id)
  RETURNING authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.completion_digest,authority_row.completion_result
 ),failed_legacy_batches AS (
  UPDATE zasp_runtime_batches batch_row SET state='failed',completed_at=transaction_timestamp()
  FROM failed_batches WHERE (batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id)
  RETURNING batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id
 ),failed_jobs AS (
  UPDATE zasp_discovery_jobs job_row SET state='failed',last_error='exhausted',completed_at=transaction_timestamp(),updated_at=transaction_timestamp(),completion_digest=failed_batches.completion_digest,completion_result=failed_batches.completion_result
  FROM failed_batches WHERE (job_row.organization_id,job_row.workspace_id,job_row.environment_id,job_row.kind,job_row.authority_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,'runtime',failed_batches.batch_id)
  RETURNING job_row.organization_id
 )
 UPDATE zasp_runtime_deliveries delivery_row SET disposition='ack_pending',updated_at=transaction_timestamp()
 FROM failed_batches WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id) AND delivery_row.disposition='held';
 WITH eligible AS (
  SELECT stage_row.ctid row_id,stage_row.*,row_number() OVER(PARTITION BY stage_row.organization_id ORDER BY stage_row.available_at,stage_row.batch_id) organization_rank
  FROM zasp_runtime_stage_work stage_row
  WHERE stage_row.stage=stage_value AND (CASE stage_value WHEN 'archive' THEN stage_row.implementation_version IN('runtime-archive-v1','runtime-archive-v2') WHEN 'index' THEN stage_row.implementation_version IN('runtime-index-v1','runtime-index-v2') WHEN 'correlate' THEN stage_row.implementation_version IN('runtime-correlation-v1','runtime-correlation-v2','runtime-correlation-v3','runtime-correlation-v4') WHEN 'project' THEN stage_row.implementation_version IN('runtime-projection-v1','runtime-projection-v2','runtime-projection-v3') WHEN 'complete' THEN stage_row.implementation_version IN('runtime-complete-v1','runtime-complete-v2','runtime-complete-v3') ELSE false END) AND stage_row.attempt<100 AND stage_row.available_at<=transaction_timestamp() AND (stage_row.state IN('pending','retryable') OR stage_row.state='leased' AND stage_row.lease_expires_at<=transaction_timestamp())
   AND stage_row.input_digest IS NOT NULL
   AND EXISTS(SELECT 1 FROM zasp_runtime_deliveries delivery_row WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id,delivery_row.batch_generation,delivery_row.disposition)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation,'held') AND delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp())
   AND (stage_row.stage_order=1 OR EXISTS(SELECT 1 FROM zasp_runtime_stage_work predecessor WHERE (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order,predecessor.state,predecessor.effect_digest)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage_order-1,'succeeded',stage_row.predecessor_digest)))
   AND NOT EXISTS(SELECT 1 FROM zasp_runtime_stage_work live_row WHERE live_row.stage=stage_value AND live_row.organization_id=stage_row.organization_id AND live_row.state='leased' AND live_row.lease_expires_at>transaction_timestamp())
 ),organizations AS (
  SELECT eligible.organization_id,min(eligible.available_at) first_available,MAX(fairness.last_claimed_at) last_claimed_at
  FROM eligible LEFT JOIN zasp_runtime_stage_fairness fairness ON (fairness.stage,fairness.organization_id)=(stage_value,eligible.organization_id)
  WHERE eligible.organization_rank=1 GROUP BY eligible.organization_id
  ORDER BY MAX(fairness.last_claimed_at) NULLS FIRST,min(eligible.available_at),eligible.organization_id LIMIT claim_limit
 ),candidates AS (
  SELECT stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage
  FROM zasp_runtime_stage_work stage_row JOIN eligible ON stage_row.ctid=eligible.row_id JOIN organizations ON organizations.organization_id=eligible.organization_id
  WHERE eligible.organization_rank=1 ORDER BY organizations.last_claimed_at NULLS FIRST,organizations.first_available,stage_row.organization_id,stage_row.batch_id FOR UPDATE OF stage_row SKIP LOCKED
 ),claimed AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='leased',attempt=stage_row.attempt+1,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),last_heartbeat_at=transaction_timestamp(),last_error_class=NULL
  FROM candidates WHERE (stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage)=(candidates.organization_id,candidates.workspace_id,candidates.environment_id,candidates.batch_id,candidates.stage)
  RETURNING stage_row.*
 ),fairness AS (
  INSERT INTO zasp_runtime_stage_fairness(stage,organization_id,last_claimed_at) SELECT stage_value,claimed.organization_id,transaction_timestamp() FROM claimed
  ON CONFLICT(stage,organization_id) DO UPDATE SET last_claimed_at=excluded.last_claimed_at RETURNING organization_id
 )
 SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',claimed.organization_id,'workspace_id',claimed.workspace_id,'environment_id',claimed.environment_id,'batch_id',claimed.batch_id,'generation',claimed.batch_generation,'stage',claimed.stage,'attempt',claimed.attempt,'implementation_version',claimed.implementation_version,'predecessor_digest',CASE WHEN claimed.predecessor_digest IS NULL THEN NULL ELSE encode(claimed.predecessor_digest,'hex') END,'input_digest',encode(claimed.input_digest,'hex'),'input_reference',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_reference ELSE predecessor.result_reference END,'input_version_id',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_version_id ELSE predecessor.result_version_id END,'lease_expires_at',claimed.lease_expires_at) ORDER BY claimed.organization_id,claimed.batch_id),'[]'::jsonb) INTO result_value
 FROM claimed JOIN zasp_runtime_batch_authorities authority_row ON (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.batch_generation)
 LEFT JOIN zasp_runtime_stage_work predecessor ON (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.stage_order-1);
 IF stage_value='archive' AND jsonb_array_length(result_value)>0 THEN UPDATE zasp_runtime_batch_authorities authority_row SET state='processing' WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(result_value) item WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(item->>'organization_id',item->>'workspace_id',item->>'environment_id',item->>'batch_id'));END IF;
 PERFORM set_config('zasp.runtime_precision_claim_version',prior_capability,true);
 IF NOT COALESCE(zasp_production_runtime_precision_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime precision authority unavailable';END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_finish_precise_session_projection(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, lease_token_value text, attempt_value integer, input_digest_value bytea, implementation_value text, outcome_value text, effect_digest_value bytea, result_reference_value text, result_version_value text, result_digest_value bytea, error_class_value text, retry_after_seconds integer, receipt_bytes bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE predecessor zasp_runtime_stage_work%ROWTYPE;complete_row zasp_runtime_stage_work%ROWTYPE;receipt_value jsonb;item jsonb;event_value zasp_runtime_session_events%ROWTYPE;retained zasp_runtime_session_events%ROWTYPE;result_value jsonb;ids text[]:='{}';digest_value bytea;
BEGIN
 IF NOT COALESCE(zasp_production_runtime_precision_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox authority unavailable';END IF;
 IF num_nulls(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,lease_token_value,attempt_value,input_digest_value,implementation_value,outcome_value,effect_digest_value,result_reference_value,result_version_value,result_digest_value,retry_after_seconds,receipt_bytes)>0
 OR NOT COALESCE(zasp_runtime_principal_ready('zasp_runtime_coordinator') AND zasp_runtime_stage_for_session()='complete' AND outcome_value='succeeded' AND implementation_value='runtime-complete-v3' AND octet_length(receipt_bytes) BETWEEN 1 AND 4194304,false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session projection authority rejected';
 END IF;
 SELECT * INTO predecessor FROM zasp_runtime_stage_work WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation,stage)=(organization_value,workspace_value,environment_value,batch_value,generation_value,'project') FOR SHARE;
 IF NOT FOUND OR predecessor.state<>'succeeded' OR predecessor.implementation_version<>'runtime-projection-v3' OR predecessor.result_digest IS DISTINCT FROM digest(receipt_bytes,'sha256') OR predecessor.effect_digest IS DISTINCT FROM input_digest_value THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session predecessor receipt rejected';
 END IF;
 SELECT * INTO complete_row FROM zasp_runtime_stage_work WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation,stage)=(organization_value,workspace_value,environment_value,batch_value,generation_value,'complete') FOR UPDATE;
 IF NOT FOUND OR complete_row.implementation_version<>'runtime-complete-v3' OR complete_row.predecessor_digest IS DISTINCT FROM predecessor.effect_digest OR complete_row.input_digest IS DISTINCT FROM input_digest_value THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session receipt binding rejected';
 END IF;
 receipt_value:=convert_from(receipt_bytes,'UTF8')::jsonb;
 IF NOT COALESCE(jsonb_typeof(receipt_value)='object' AND receipt_value->>'schema'='runtime-projection-receipt-v3' AND receipt_value->>'implementation_version'='runtime-projection-v3'
 AND (receipt_value->>'organization_id',receipt_value->>'workspace_id',receipt_value->>'environment_id',receipt_value->>'batch_id')=(organization_value,workspace_value,environment_value,batch_value)
 AND receipt_value->>'generation'=generation_value::text AND receipt_value->>'effect_digest'=encode(input_digest_value,'hex') AND input_digest_value=effect_digest_value
 AND jsonb_typeof(receipt_value->'items')='array' AND jsonb_array_length(receipt_value->'items') BETWEEN 1 AND 1000,false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session receipt shape rejected';
 END IF;
 IF NOT COALESCE(zasp_production_runtime_precision_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox authority unavailable';END IF;
 result_value:=zasp_runtime_finish_stage_v39(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,lease_token_value,attempt_value,input_digest_value,implementation_value,outcome_value,effect_digest_value,result_reference_value,result_version_value,result_digest_value,error_class_value,retry_after_seconds);
 FOR item IN SELECT value FROM jsonb_array_elements(receipt_value->'items') LOOP
  event_value.organization_id:=organization_value;event_value.workspace_id:=workspace_value;event_value.environment_id:=environment_value;
  event_value.event_id:=item->>'event_id';event_value.session_id:=NULLIF(item->>'session_id','');event_value.agent_id:=NULLIF(item->>'agent_id','');
  event_value.confidence:=item->>'confidence';event_value.source:=item->>'source';event_value.event_class:=item->>'event_class';event_value.action:=item->>'action';
  event_value.title:=item->>'title';event_value.evidence_id:=item->>'evidence_id';event_value.event_time:=(item->>'event_time')::timestamptz;event_value.projected_at:=transaction_timestamp();

  IF (item ? 'sandbox_id')<>(item ? 'sandbox_source_sensor_id')
  OR item ? 'sandbox_id' AND (jsonb_typeof(item->'sandbox_id') IS DISTINCT FROM 'string' OR jsonb_typeof(item->'sandbox_source_sensor_id') IS DISTINCT FROM 'string')
  OR item->>'confidence'='exact' AND NOT (item ? 'sandbox_id')
  OR event_value.agent_id IS NOT NULL AND event_value.agent_id=event_value.session_id
  THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session sandbox shape rejected';END IF;
  IF item->>'source' IS DISTINCT FROM 'tetragon' OR item->>'confidence'='exact' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime precise session source rejected';END IF;
  event_value.sandbox_id:=item->>'sandbox_id';event_value.sandbox_source_sensor_id:=item->>'sandbox_source_sensor_id';

  IF event_value.event_id=ANY(ids) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session duplicate event rejected';END IF;
  ids:=array_append(ids,event_value.event_id);
  INSERT INTO zasp_runtime_session_events SELECT (event_value).* ON CONFLICT DO NOTHING;
  SELECT * INTO STRICT retained FROM zasp_runtime_session_events WHERE (organization_id,workspace_id,environment_id,event_id)=(organization_value,workspace_value,environment_value,event_value.event_id);
  IF (to_jsonb(retained)-'projected_at') IS DISTINCT FROM (to_jsonb(event_value)-'projected_at') THEN
   RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime session event replay conflict';
  END IF;
 END LOOP;
 digest_value:=digest(receipt_bytes,'sha256');
 INSERT INTO zasp_runtime_session_projection_receipts VALUES(organization_value,workspace_value,environment_value,batch_value,generation_value,digest_value,ids) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM zasp_runtime_session_projection_receipts WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation,receipt_digest,event_ids)=(organization_value,workspace_value,environment_value,batch_value,generation_value,digest_value,ids)) THEN
  RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime session receipt replay conflict';
 END IF;
 IF NOT COALESCE(zasp_production_runtime_precision_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox authority unavailable';END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_freeze_precise_candidates(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, lease_token_value text, attempt_value integer, implementation_value text, input_digest_value bytea, index_receipt_value bytea, archive_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE work_row zasp_runtime_stage_work%ROWTYPE;batch_row zasp_runtime_batch_authorities%ROWTYPE;domain_row zasp_runtime_batch_domains%ROWTYPE;index_row zasp_runtime_stage_work%ROWTYPE;prior zasp_runtime_candidate_snapshots%ROWTYPE;
 receipt jsonb;archive jsonb;event_value jsonb;ordinal_value bigint;archive_digest_value bytea;receipt_digest_value bytea;now_value timestamptz;candidate_values jsonb;body_value bytea;body_digest bytea;possible_count integer;
BEGIN
 IF NOT COALESCE(zasp_production_runtime_precision_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox authority unavailable';END IF;
 IF NOT COALESCE(zasp_runtime_principal_ready('zasp_runtime_correlation_worker') AND zasp_runtime_stage_for_session()='correlate',false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime candidate principal rejected';END IF;
 IF NOT COALESCE(zasp_valid_product_id(organization_value) AND zasp_valid_product_id(workspace_value) AND zasp_valid_product_id(environment_value) AND zasp_valid_product_id(batch_value) AND generation_value>0 AND worker_value ~ '^[a-z][a-z0-9.-]{2,127}$' AND lease_token_value ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' AND attempt_value BETWEEN 1 AND 100 AND implementation_value='runtime-correlation-v4' AND octet_length(input_digest_value)=32 AND octet_length(index_receipt_value) BETWEEN 1 AND 1048576 AND octet_length(archive_value) BETWEEN 1 AND 67108864,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime candidate input rejected';END IF;
 SELECT * INTO work_row FROM zasp_runtime_stage_work WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation,stage)=(organization_value,workspace_value,environment_value,batch_value,generation_value,'correlate') FOR UPDATE;
 now_value:=clock_timestamp();
 IF NOT FOUND OR work_row.state<>'leased' OR work_row.lease_owner IS DISTINCT FROM worker_value OR work_row.lease_token IS DISTINCT FROM lease_token_value OR work_row.attempt IS DISTINCT FROM attempt_value OR work_row.implementation_version IS DISTINCT FROM implementation_value OR work_row.input_digest IS DISTINCT FROM input_digest_value OR work_row.lease_expires_at<=now_value THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime candidate lease missing';END IF;
 SELECT * INTO STRICT batch_row FROM zasp_runtime_batch_authorities WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value);
 SELECT * INTO STRICT domain_row FROM zasp_runtime_batch_domains WHERE (organization_id,workspace_id,environment_id,batch_id,generation,source_sensor_id,source_kind)=(organization_value,workspace_value,environment_value,batch_value,generation_value,batch_row.sensor_id,batch_row.source_kind);
 IF domain_row.source_kind<>'tetragon' OR domain_row.runtime_sensor_id IS DISTINCT FROM domain_row.source_sensor_id OR batch_row.payload_schema_version<>'runtime-event-v2' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime precise archive schema rejected';END IF;
 SELECT * INTO STRICT index_row FROM zasp_runtime_stage_work WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation,stage,state)=(organization_value,workspace_value,environment_value,batch_value,generation_value,'index','succeeded');
 archive_digest_value:=digest(archive_value,'sha256');receipt_digest_value:=digest(index_receipt_value,'sha256');
 IF index_row.implementation_version<>'runtime-index-v2' OR batch_row.state<>'processing' OR batch_row.raw_artifact_checksum IS DISTINCT FROM archive_digest_value OR batch_row.content_digest IS DISTINCT FROM archive_digest_value OR batch_row.raw_artifact_size_bytes IS DISTINCT FROM octet_length(archive_value)::bigint OR index_row.result_digest IS DISTINCT FROM receipt_digest_value OR index_row.effect_digest IS DISTINCT FROM input_digest_value OR work_row.predecessor_digest IS DISTINCT FROM index_row.effect_digest OR index_row.input_digest IS DISTINCT FROM archive_digest_value OR index_row.predecessor_digest IS DISTINCT FROM archive_digest_value THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime candidate predecessor rejected';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_runtime_stage_work WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation,stage,implementation_version,state,effect_digest,result_reference,result_version_id)=(organization_value,workspace_value,environment_value,batch_value,generation_value,'archive','runtime-archive-v2','succeeded',archive_digest_value,batch_row.raw_artifact_reference,batch_row.raw_artifact_version_id)) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime candidate archive predecessor rejected';END IF;
 receipt:=convert_from(index_receipt_value,'UTF8')::jsonb;archive:=convert_from(archive_value,'UTF8')::jsonb;
 IF NOT COALESCE(receipt->>'schema'='runtime-stage-receipt-v1' AND receipt->>'stage'='index' AND receipt->>'implementation_version'='runtime-index-v2' AND receipt->>'organization_id'=organization_value AND receipt->>'workspace_id'=workspace_value AND receipt->>'environment_id'=environment_value AND receipt->>'batch_id'=batch_value AND receipt->>'generation'=generation_value::text AND receipt->>'effect_digest'=encode(input_digest_value,'hex') AND receipt->>'archive_digest'=encode(archive_digest_value,'hex') AND receipt->>'archive_reference'=batch_row.raw_artifact_reference AND receipt->>'archive_version_id'=batch_row.raw_artifact_version_id AND receipt->>'input_digest'=encode(archive_digest_value,'hex') AND receipt->>'input_reference'=batch_row.raw_artifact_reference AND receipt->>'input_version_id'=batch_row.raw_artifact_version_id AND archive->>'version'='runtime-archive-v2' AND archive->>'source'=domain_row.source_kind AND jsonb_typeof(archive->'events')='array' AND jsonb_array_length(archive->'events')=batch_row.event_count,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime candidate archive binding rejected';END IF;
 SELECT * INTO prior FROM zasp_runtime_candidate_snapshots WHERE (organization_id,workspace_id,environment_id,batch_id,generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value);
 IF FOUND THEN
  IF convert_from(prior.snapshot_body,'UTF8')::jsonb->>'schema' IS DISTINCT FROM 'runtime-candidate-snapshot-v3' THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime sandbox replay version conflict';END IF;
  IF prior.archive_digest IS DISTINCT FROM archive_digest_value OR prior.index_receipt_digest IS DISTINCT FROM receipt_digest_value THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime candidate replay conflict';END IF;
  PERFORM zasp_runtime_candidate_execution_live(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,lease_token_value,attempt_value,implementation_value,input_digest_value,archive_digest_value,receipt_digest_value);
  IF NOT COALESCE(zasp_production_runtime_precision_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox authority unavailable';END IF;
 RETURN jsonb_build_object('snapshot',encode(prior.snapshot_body,'hex'),'sha256',encode(prior.snapshot_digest,'hex'),'replayed',true);
 END IF;
 -- Only the two admission identities are locked. Existing candidate identities
 -- are sampled in the selection statement; a later revocation cannot rewrite
 -- an already frozen historical decision. Never lock another batch's stage.
 PERFORM id FROM zasp_sensors WHERE (organization_id,workspace_id,environment_id)=(organization_value,workspace_value,environment_value) AND id IN(domain_row.source_sensor_id,domain_row.runtime_sensor_id) ORDER BY id FOR SHARE;
 now_value:=clock_timestamp();
 IF work_row.lease_expires_at<=now_value OR NOT zasp_runtime_principal_ready('zasp_runtime_correlation_worker') OR NOT EXISTS(SELECT 1 FROM zasp_sensors WHERE (organization_id,workspace_id,environment_id,id,kind,state)=(organization_value,workspace_value,environment_value,domain_row.source_sensor_id,domain_row.source_kind,'active') AND revoked_at IS NULL) OR domain_row.runtime_sensor_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM zasp_sensors WHERE (organization_id,workspace_id,environment_id,id,kind,state)=(organization_value,workspace_value,environment_value,domain_row.runtime_sensor_id,'tetragon','active') AND revoked_at IS NULL) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime candidate enrollment rejected';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_runtime_deliveries WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation,disposition)=(organization_value,workspace_value,environment_value,batch_value,generation_value,'held') AND lease_expires_at>now_value AND visibility_deadline>now_value) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime candidate delivery missing';END IF;
 FOR event_value,ordinal_value IN SELECT value,ordinality FROM jsonb_array_elements(archive->'events') WITH ORDINALITY LOOP
  IF event_value ? 'observed_lineage' AND NOT zasp_runtime_precise_lineage_valid(event_value->'observed_lineage',event_value->>'event_time') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime candidate lineage rejected';END IF;
  IF domain_row.source_kind='otlp' AND domain_row.runtime_sensor_id IS NOT NULL AND event_value ? 'observed_lineage' THEN
   IF jsonb_typeof(event_value#>'{attributes,sandbox.id}') IS DISTINCT FROM 'string' OR COALESCE(octet_length(event_value#>>'{attributes,sandbox.id}'),0) NOT BETWEEN 1 AND 256 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime sandbox identity rejected';END IF;
   INSERT INTO zasp_runtime_candidate_observations(organization_id,workspace_id,environment_id,batch_id,generation,event_ordinal,source_sensor_id,runtime_sensor_id,archive_digest,index_receipt_digest,agent_id,session_id,observed_lineage,event_time,cluster_uid,node_uid,boot_id,pod_uid,container_id,sandbox_id)
   VALUES(organization_value,workspace_value,environment_value,batch_value,generation_value,ordinal_value,domain_row.source_sensor_id,domain_row.runtime_sensor_id,archive_digest_value,receipt_digest_value,event_value#>>'{attributes,agent.id}',event_value#>>'{attributes,session.id}',event_value->'observed_lineage',(event_value->>'event_time')::timestamptz,event_value#>>'{observed_lineage,cluster_uid}',event_value#>>'{observed_lineage,node_uid}',event_value#>>'{observed_lineage,boot_id}',event_value#>>'{observed_lineage,pod_uid}',event_value#>>'{observed_lineage,container_id}',event_value#>>'{attributes,sandbox.id}');
  END IF;
 END LOOP;
 -- Fixed five-minute event-time profile. At most 1,001 indexed observations
 -- per input event; an overflowing union fails closed rather than truncating.
 WITH targets AS MATERIALIZED (SELECT DISTINCT value->'observed_lineage' lineage,(value->>'event_time')::timestamptz event_time,zasp_runtime_precise_epoch(value#>>'{observed_lineage,source_event_time}') source_epoch FROM jsonb_array_elements(archive->'events') WHERE value ? 'observed_lineage'),
 possible AS MATERIALIZED (
  SELECT selected.* FROM targets target CROSS JOIN LATERAL (
   SELECT observation.batch_id,observation.event_ordinal FROM zasp_runtime_candidate_observations observation
   WHERE (observation.organization_id,observation.workspace_id,observation.environment_id,observation.runtime_sensor_id,observation.cluster_uid,observation.node_uid,observation.boot_id,observation.pod_uid,observation.container_id)=(organization_value,workspace_value,environment_value,domain_row.runtime_sensor_id,target.lineage->>'cluster_uid',target.lineage->>'node_uid',target.lineage->>'boot_id',target.lineage->>'pod_uid',target.lineage->>'container_id')
    AND observation.event_time BETWEEN target.event_time-interval '5 minutes' AND target.event_time+interval '5 minutes'+interval '1 millisecond'
    AND abs(extract(epoch FROM observation.event_time)-target.source_epoch)<=300
   ORDER BY observation.event_time,observation.batch_id,observation.event_ordinal LIMIT 1001
  ) selected
 ), unique_rows AS MATERIALIZED (SELECT DISTINCT * FROM possible), selected AS (
  SELECT observation.* FROM unique_rows occurrence
  JOIN zasp_runtime_candidate_observations observation ON (observation.organization_id,observation.workspace_id,observation.environment_id,observation.batch_id,observation.event_ordinal)=(organization_value,workspace_value,environment_value,occurrence.batch_id,occurrence.event_ordinal)
  JOIN zasp_sensors source ON (source.organization_id,source.workspace_id,source.environment_id,source.id,source.kind,source.state)=(observation.organization_id,observation.workspace_id,observation.environment_id,observation.source_sensor_id,'otlp','active') AND source.revoked_at IS NULL
  JOIN zasp_runtime_batch_authorities origin ON (origin.organization_id,origin.workspace_id,origin.environment_id,origin.batch_id,origin.batch_generation)=(observation.organization_id,observation.workspace_id,observation.environment_id,observation.batch_id,observation.generation) AND origin.state IN('processing','succeeded')
  ORDER BY observation.batch_id,observation.event_ordinal LIMIT 1001
 ) SELECT COALESCE(jsonb_agg(jsonb_build_object('batch_id',batch_id,'generation',generation,'event_ordinal',event_ordinal,'source_sensor_id',source_sensor_id,'agent_id',agent_id,'session_id',session_id,'sandbox_id',sandbox_id,'archive_digest',encode(archive_digest,'hex'),'index_receipt_digest',encode(index_receipt_digest,'hex'),'observed_lineage',observed_lineage,'event_time',to_char(event_time AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) ORDER BY batch_id,event_ordinal),'[]'::jsonb),(SELECT count(*) FROM (SELECT 1 FROM unique_rows LIMIT 1001) bounded)
 INTO candidate_values,possible_count FROM selected;
 -- Detect overflow BEFORE authority filtering: revoked/failed rows must never
 -- occupy the internal bound and hide another viable identity beyond it.
 IF possible_count>1000 OR jsonb_array_length(candidate_values)>1000 THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='runtime candidate snapshot overflow';END IF;
 body_value:=convert_to(jsonb_build_object('schema','runtime-candidate-snapshot-v3','organization_id',organization_value,'workspace_id',workspace_value,'environment_id',environment_value,'batch_id',batch_value,'generation',generation_value,'source_sensor_id',domain_row.source_sensor_id,'runtime_sensor_id',domain_row.runtime_sensor_id,'archive_digest',encode(archive_digest_value,'hex'),'index_receipt_digest',encode(receipt_digest_value,'hex'),'window_seconds',300,'candidates',candidate_values)::text,'UTF8');
 body_digest:=digest(body_value,'sha256');
 IF clock_timestamp()>=work_row.lease_expires_at THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime candidate lease expired';END IF;
 INSERT INTO zasp_runtime_candidate_snapshots(organization_id,workspace_id,environment_id,batch_id,generation,source_sensor_id,source_kind,runtime_sensor_id,archive_digest,index_receipt_digest,snapshot_body,snapshot_digest)
 VALUES(organization_value,workspace_value,environment_value,batch_value,generation_value,domain_row.source_sensor_id,domain_row.source_kind,domain_row.runtime_sensor_id,archive_digest_value,receipt_digest_value,body_value,body_digest);
 PERFORM zasp_runtime_candidate_execution_live(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,lease_token_value,attempt_value,implementation_value,input_digest_value,archive_digest_value,receipt_digest_value);
 IF NOT COALESCE(zasp_production_runtime_precision_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox authority unavailable';END IF;
 RETURN jsonb_build_object('snapshot',encode(body_value,'hex'),'sha256',encode(body_digest,'hex'),'replayed',false);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_precise_epoch(value text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE whole_value timestamptz; seconds_value numeric; fraction_value text;
BEGIN
 IF octet_length(value) NOT BETWEEN 20 AND 30 OR value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{0,8}[1-9])?Z$' THEN RETURN NULL;END IF;
 -- Never cast fractional source time to timestamptz: PostgreSQL would round
 -- nanoseconds to microseconds before validation or occurrence-window matching.
 whole_value := (left(value,19)||'Z')::timestamptz;
 IF to_char(whole_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')<>left(value,19) THEN RETURN NULL;END IF;
 seconds_value := extract(epoch FROM whole_value);
 IF seconds_value<=0 THEN RETURN NULL;END IF;
 IF length(value)>20 THEN
  fraction_value := substring(value FROM 21 FOR length(value)-21);
  seconds_value := seconds_value+('0.'||fraction_value)::numeric;
 END IF;
 RETURN seconds_value;
EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow OR invalid_text_representation OR numeric_value_out_of_range THEN RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_precise_lineage_valid(value jsonb, event_time_value text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE key_value text; identifier text; source_value numeric; start_value numeric; wire_value timestamptz;
BEGIN
 IF value IS NULL OR jsonb_typeof(value)<>'object' OR event_time_value IS NULL OR value->>'profile' IS DISTINCT FROM 'kubernetes-container-v2' OR octet_length(value::text)>1280 THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(value) member WHERE member.key NOT IN('profile','cluster_uid','node_uid','boot_id','pod_uid','container_id','process_id','process_start_time','cgroup_id','source_event_time') OR jsonb_typeof(member.value)<>'string' OR member.value='""'::jsonb) THEN RETURN false;END IF;
 FOREACH key_value IN ARRAY ARRAY['cluster_uid','node_uid','boot_id','pod_uid'] LOOP
  identifier:=value->>key_value;
  IF NOT COALESCE(identifier ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND identifier<>'00000000-0000-0000-0000-000000000000',false) THEN RETURN false;END IF;
 END LOOP;
 IF NOT COALESCE(value->>'container_id' ~ '^(containerd|docker|cri-o)://[0-9a-f]{64}$' AND right(value->>'container_id',64)<>repeat('0',64),false) THEN RETURN false;END IF;
 source_value:=zasp_runtime_precise_epoch(value->>'source_event_time');
 IF source_value IS NULL OR octet_length(event_time_value)<>24 OR event_time_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' THEN RETURN false;END IF;
 -- Display time is deliberately millisecond precision. Its full canonical
 -- spelling is checked separately from the nanosecond source-time contract.
 wire_value:=event_time_value::timestamptz;
 IF to_char(wire_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')<>event_time_value OR trunc(source_value,3)<>extract(epoch FROM wire_value) THEN RETURN false;END IF;
 IF (value ? 'process_id') IS DISTINCT FROM (value ? 'process_start_time') THEN RETURN false;END IF;
 IF value ? 'process_id' THEN
  IF value->>'process_id' !~ '^[1-9][0-9]{0,9}$' OR (value->>'process_id')::numeric>4294967295 THEN RETURN false;END IF;
  start_value:=zasp_runtime_precise_epoch(value->>'process_start_time');
  IF start_value IS NULL OR start_value>source_value THEN RETURN false;END IF;
 END IF;
 IF value ? 'cgroup_id' AND (value->>'cgroup_id' !~ '^[1-9][0-9]{0,19}$' OR (value->>'cgroup_id')::numeric>18446744073709551615) THEN RETURN false;END IF;
 RETURN true;
EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow OR invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_precise_search_claim(worker_value text, token_value text, lease_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prior_capability text;work zasp_runtime_sandbox_search_outbox%ROWTYPE;now_value timestamptz:=clock_timestamp();
BEGIN
 prior_capability:=COALESCE(current_setting('zasp.runtime_precision_search_claim',true),'');
 PERFORM set_config('zasp.runtime_precision_search_claim','runtime-projection-v3',true);
 IF num_nulls(worker_value,token_value,lease_seconds)>0 OR worker_value !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$' OR token_value !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' OR lease_seconds NOT BETWEEN 5 AND 900
 OR NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime sandbox search worker rejected';END IF;
 FOR work IN SELECT * FROM zasp_runtime_sandbox_search_outbox q WHERE q.state IN('pending','leased') AND q.attempt>=100 AND (q.lease_until IS NULL OR q.lease_until<=now_value)
 AND EXISTS(SELECT 1 FROM zasp_runtime_stage_work project WHERE (project.organization_id,project.workspace_id,project.environment_id,project.batch_id,project.batch_generation)=(q.organization_id,q.workspace_id,q.environment_id,q.batch_id,q.batch_generation) AND project.stage='project' AND project.state='succeeded' AND project.implementation_version IN('runtime-projection-v1','runtime-projection-v2','runtime-projection-v3'))
 AND NOT EXISTS(SELECT 1 FROM zasp_recovery_holds h WHERE (h.organization_id,h.workspace_id,h.environment_id)=(q.organization_id,q.workspace_id,q.environment_id) AND h.state IN('requested','draining','held'))
 ORDER BY q.next_attempt_at,q.created_at,q.organization_id,q.workspace_id,q.environment_id,q.batch_id,q.batch_generation FOR UPDATE OF q SKIP LOCKED LIMIT 100 LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'zasp-recovery-hold',work.organization_id,work.workspace_id,work.environment_id),0)) THEN CONTINUE;END IF;
  IF NOT zasp_recovery_scope_mutable(work.organization_id,work.workspace_id,work.environment_id) THEN CONTINUE;END IF;
  IF NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;
  UPDATE zasp_runtime_sandbox_search_outbox SET state='quarantined',worker_id=NULL,lease_digest=NULL,lease_until=NULL
  WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation)=(work.organization_id,work.workspace_id,work.environment_id,work.batch_id,work.batch_generation);
 END LOOP;
 FOR work IN SELECT * FROM zasp_runtime_sandbox_search_outbox q WHERE q.attempt<100 AND ((q.state='pending' AND q.next_attempt_at<=now_value) OR (q.state='leased' AND q.lease_until<=now_value))
 AND EXISTS(SELECT 1 FROM zasp_runtime_stage_work project WHERE (project.organization_id,project.workspace_id,project.environment_id,project.batch_id,project.batch_generation)=(q.organization_id,q.workspace_id,q.environment_id,q.batch_id,q.batch_generation) AND project.stage='project' AND project.state='succeeded' AND project.implementation_version IN('runtime-projection-v1','runtime-projection-v2','runtime-projection-v3'))
 AND NOT EXISTS(SELECT 1 FROM zasp_recovery_holds h WHERE (h.organization_id,h.workspace_id,h.environment_id)=(q.organization_id,q.workspace_id,q.environment_id) AND h.state IN('requested','draining','held'))
 ORDER BY q.next_attempt_at,q.created_at,q.organization_id,q.workspace_id,q.environment_id,q.batch_id,q.batch_generation FOR UPDATE OF q SKIP LOCKED LIMIT 100 LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'zasp-recovery-hold',work.organization_id,work.workspace_id,work.environment_id),0)) THEN CONTINUE;END IF;
  IF NOT zasp_recovery_scope_mutable(work.organization_id,work.workspace_id,work.environment_id) THEN CONTINUE;END IF;
  IF NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;
  now_value:=clock_timestamp();
  UPDATE zasp_runtime_sandbox_search_outbox SET state='leased',attempt=attempt+1,worker_id=worker_value,lease_digest=digest(convert_to(token_value,'UTF8'),'sha256'),lease_until=now_value+make_interval(secs=>lease_seconds)
  WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation)=(work.organization_id,work.workspace_id,work.environment_id,work.batch_id,work.batch_generation) RETURNING * INTO work;
  IF NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;
  PERFORM set_config('zasp.runtime_precision_search_claim',prior_capability,true);
  RETURN jsonb_build_object('projection_implementation_version',(SELECT project.implementation_version FROM zasp_runtime_stage_work project WHERE (project.organization_id,project.workspace_id,project.environment_id,project.batch_id,project.batch_generation)=(work.organization_id,work.workspace_id,work.environment_id,work.batch_id,work.batch_generation) AND project.stage='project' AND project.state='succeeded'),'organization_id',work.organization_id,'workspace_id',work.workspace_id,'environment_id',work.environment_id,'batch_id',work.batch_id,'generation',work.batch_generation,'receipt_digest',encode(work.receipt_digest,'hex'),'receipt_reference',work.receipt_reference,'receipt_version',work.receipt_version,'document_ids',work.document_ids,'attempt',work.attempt,'lease_until',work.lease_until);
 END LOOP;
 IF NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;
 PERFORM set_config('zasp.runtime_precision_search_claim',prior_capability,true);
 RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_precision_claim_outbox(topic_value text, worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer, allow_v2 boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE response jsonb;prior_capability text;last_organization text;claimed_last_organization text;
BEGIN
 PERFORM zasp_runtime_precision_transport_ready();
 IF topic_value IS NULL OR worker_value IS NULL OR lease_token_value IS NULL OR lease_seconds IS NULL OR claim_limit IS NULL OR allow_v2 IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime outbox claim rejected';END IF;
 IF allow_v2 AND NOT zasp_discovery_principal_ready('zasp_outbox_worker') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime precise outbox principal rejected';END IF;
 prior_capability:=COALESCE(current_setting('zasp.runtime_precision_outbox_claim',true),'');
 PERFORM set_config('zasp.runtime_precision_outbox_claim',CASE WHEN allow_v2 THEN 'runtime-event-v2' ELSE '' END,true);
 IF topic_value<>'runtime-events' OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid runtime outbox claim';END IF;
 IF NOT pg_has_role(session_user,'zasp_outbox_worker','MEMBER') AND NOT pg_has_role(session_user,'zasp_discovery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime outbox authority denied';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp_runtime_outbox:'||topic_value,0));
 INSERT INTO zasp_discovery_outbox_topic_fairness(topic) VALUES(topic_value) ON CONFLICT(topic) DO NOTHING;
 SELECT last_organization_id INTO last_organization FROM zasp_discovery_outbox_topic_fairness WHERE topic=topic_value FOR UPDATE;
 UPDATE zasp_discovery_outbox SET state='exhausted',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_error=COALESCE(last_error,'maximum publish attempts exhausted')
 WHERE topic=topic_value AND (payload->>'payload_schema_version'='runtime-event-v1' OR allow_v2 AND payload->>'payload_schema_version'='runtime-event-v2') AND attempt>=100 AND (state='failed' OR state='leased' AND lease_expires_at<=transaction_timestamp());
 WITH organizations AS (
  SELECT candidate.organization_id,min(candidate.available_at) due FROM zasp_discovery_outbox candidate
  WHERE candidate.topic=topic_value AND (candidate.payload->>'payload_schema_version'='runtime-event-v1' OR allow_v2 AND candidate.payload->>'payload_schema_version'='runtime-event-v2') AND candidate.attempt<100 AND (candidate.state IN('pending','failed') OR candidate.state='leased' AND candidate.lease_expires_at<=transaction_timestamp()) AND candidate.available_at<=transaction_timestamp()
    AND NOT EXISTS(SELECT 1 FROM zasp_discovery_outbox live WHERE live.topic=topic_value AND live.organization_id=candidate.organization_id AND live.state='leased' AND live.lease_expires_at>transaction_timestamp())
  GROUP BY candidate.organization_id
 ),ordered_organizations AS (
  SELECT organization_id,due,row_number() OVER(ORDER BY CASE WHEN last_organization IS NULL OR organization_id>last_organization THEN 0 ELSE 1 END,organization_id) fair_order
  FROM organizations ORDER BY fair_order LIMIT claim_limit
 ),picked AS (
  SELECT chosen.ctid,chosen.organization_id,chosen.created_at,chosen.id,organization.fair_order FROM ordered_organizations organization
  CROSS JOIN LATERAL (
   SELECT outbox.ctid,outbox.organization_id,outbox.created_at,outbox.id FROM zasp_discovery_outbox outbox
   WHERE outbox.organization_id=organization.organization_id AND outbox.topic=topic_value AND (outbox.payload->>'payload_schema_version'='runtime-event-v1' OR allow_v2 AND outbox.payload->>'payload_schema_version'='runtime-event-v2') AND outbox.attempt<100
     AND (outbox.state IN('pending','failed') OR outbox.state='leased' AND outbox.lease_expires_at<=transaction_timestamp()) AND outbox.available_at<=transaction_timestamp()
   ORDER BY outbox.created_at,outbox.id LIMIT 1 FOR UPDATE SKIP LOCKED
  ) chosen
 ),claimed AS (
  UPDATE zasp_discovery_outbox outbox SET state='leased',attempt=attempt+1,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),completion_digest=NULL,completion_result=NULL
  FROM (SELECT * FROM picked ORDER BY fair_order) candidate WHERE outbox.ctid=candidate.ctid
  RETURNING outbox.organization_id,outbox.workspace_id,outbox.environment_id,outbox.id,outbox.topic,outbox.deterministic_key,outbox.payload_version,outbox.payload,encode(outbox.payload_digest,'base64') payload_digest,outbox.attempt,outbox.lease_expires_at,candidate.fair_order
 )
 SELECT jsonb_build_object('items',COALESCE(jsonb_agg(to_jsonb(claimed)-'fair_order' ORDER BY fair_order),'[]'::jsonb)),(array_agg(organization_id ORDER BY fair_order DESC))[1] INTO response,claimed_last_organization FROM claimed;
 IF claimed_last_organization IS NOT NULL THEN UPDATE zasp_discovery_outbox_topic_fairness SET last_organization_id=claimed_last_organization,updated_at=transaction_timestamp() WHERE topic=topic_value;END IF;
 PERFORM zasp_runtime_precision_transport_ready();
 PERFORM set_config('zasp.runtime_precision_outbox_claim',prior_capability,true);
 RETURN response;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_precision_claim_reconciliation(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer, allow_v2 boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE response jsonb;prior_capability text;
BEGIN
 PERFORM zasp_runtime_precision_reconciliation_ready();
 IF worker_value IS NULL OR lease_token_value IS NULL OR lease_seconds IS NULL OR claim_limit IS NULL OR allow_v2 IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime reconciliation claim rejected';END IF;
 prior_capability:=COALESCE(current_setting('zasp.runtime_precision_reconciliation_claim',true),'');
 PERFORM set_config('zasp.runtime_precision_reconciliation_claim',CASE WHEN allow_v2 THEN 'runtime-event-v2' ELSE '' END,true);
 UPDATE zasp_runtime_ingest_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
 IF NOT zasp_discovery_principal_ready('zasp_runtime_ingest') OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 60 AND 300 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime reconciliation claim rejected';END IF;
 UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state='succeeded',completion_worker='observed',completion_token_digest=digest(convert_to('observed','UTF8'),'sha256'),completion_digest=digest(convert_to(authority_row.completion_result::text,'UTF8'),'sha256'),completion_result=COALESCE(authority_row.completion_result,jsonb_build_object('batch_id',authority_row.batch_id,'generation',authority_row.batch_generation,'state',authority_row.state,'replayed',true)),completed_at=transaction_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL
 FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id) AND authority_row.batch_generation=work_row.batch_generation AND (authority_row.payload_schema_version='runtime-event-v1' OR allow_v2 AND authority_row.payload_schema_version='runtime-event-v2') AND work_row.state NOT IN('succeeded','quarantined') AND authority_row.state NOT IN('uploading','unknown');
 UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state=CASE WHEN attempt>=100 THEN 'exhausted' ELSE 'retryable' END,available_at=transaction_timestamp(),last_error_code=CASE WHEN attempt>=100 THEN 'exhausted' ELSE 'outcome_unknown' END,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL WHERE state='leased' AND lease_expires_at<=transaction_timestamp() AND EXISTS(SELECT 1 FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id,work_row.batch_generation) AND (authority_row.payload_schema_version='runtime-event-v1' OR allow_v2 AND authority_row.payload_schema_version='runtime-event-v2'));
 WITH candidates AS (
  SELECT work_row.ctid FROM zasp_runtime_ingest_reconciliation_work work_row JOIN zasp_runtime_batch_authorities authority_row USING(organization_id,workspace_id,environment_id,batch_id)
  WHERE authority_row.batch_generation=work_row.batch_generation AND (authority_row.payload_schema_version='runtime-event-v1' OR allow_v2 AND authority_row.payload_schema_version='runtime-event-v2') AND work_row.state IN('pending','retryable') AND work_row.attempt<100 AND work_row.available_at<=transaction_timestamp() AND authority_row.state IN('uploading','unknown') ORDER BY work_row.available_at,work_row.organization_id,work_row.batch_id FOR UPDATE OF work_row SKIP LOCKED LIMIT claim_limit
 ),claimed AS (
  UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state='leased',attempt=work_row.attempt+1,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),last_error_code=NULL FROM candidates WHERE work_row.ctid=candidates.ctid
  RETURNING work_row.*
 ) SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',claimed.organization_id,'workspace_id',claimed.workspace_id,'environment_id',claimed.environment_id,'batch_id',claimed.batch_id,'generation',claimed.batch_generation,'attempt',claimed.attempt,'lease_expires_at',claimed.lease_expires_at,'request_digest',encode(authority_row.request_digest,'hex'),'artifact_key',authority_row.raw_artifact_key,'content_digest',encode(authority_row.content_digest,'hex'),'payload_size_bytes',authority_row.payload_size_bytes,'media_type',authority_row.payload_media_type,'schema_version',authority_row.payload_schema_version) ORDER BY claimed.organization_id,claimed.batch_id),'[]'::jsonb) INTO response FROM claimed JOIN zasp_runtime_batch_authorities authority_row USING(organization_id,workspace_id,environment_id,batch_id);
 PERFORM zasp_runtime_precision_reconciliation_ready();
 PERFORM set_config('zasp.runtime_precision_reconciliation_claim',prior_capability,true);
 RETURN response;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_precision_claim_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE expected text;authority text;
BEGIN
 IF NEW.attempt>OLD.attempt OR NEW.state='failed' AND NEW.last_error_class='exhausted' AND (OLD.state IN('pending','retryable') OR OLD.state='leased' AND OLD.lease_expires_at<=transaction_timestamp()) THEN
  IF NOT COALESCE(zasp_production_runtime_precision_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime precision authority unavailable';END IF;
  IF (CASE NEW.stage WHEN 'archive' THEN NEW.implementation_version='runtime-archive-v1' WHEN 'index' THEN NEW.implementation_version='runtime-index-v1' WHEN 'correlate' THEN NEW.implementation_version IN('runtime-correlation-v1','runtime-correlation-v2','runtime-correlation-v3') WHEN 'project' THEN NEW.implementation_version IN('runtime-projection-v1','runtime-projection-v2') WHEN 'complete' THEN NEW.implementation_version IN('runtime-complete-v1','runtime-complete-v2') ELSE false END) THEN RETURN NEW;END IF;
  expected:=CASE NEW.stage WHEN 'archive' THEN 'runtime-archive-v2' WHEN 'index' THEN 'runtime-index-v2' WHEN 'correlate' THEN 'runtime-correlation-v4' WHEN 'project' THEN 'runtime-projection-v3' WHEN 'complete' THEN 'runtime-complete-v3' END;
  authority:=CASE NEW.stage WHEN 'archive' THEN 'zasp_runtime_archive_worker' WHEN 'index' THEN 'zasp_runtime_index_worker' WHEN 'correlate' THEN 'zasp_runtime_correlation_worker' WHEN 'project' THEN 'zasp_runtime_projection_worker' WHEN 'complete' THEN 'zasp_runtime_coordinator' END;
  IF NOT COALESCE(NEW.implementation_version=expected AND current_setting('zasp.runtime_precision_claim_version',true)=expected AND zasp_runtime_stage_for_session()=NEW.stage AND zasp_runtime_principal_ready(authority),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime precision claim version rejected';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_precision_outbox_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF OLD.topic='runtime-events' AND OLD.payload->>'payload_schema_version'='runtime-event-v2' OR NEW.topic='runtime-events' AND NEW.payload->>'payload_schema_version'='runtime-event-v2' THEN
  PERFORM zasp_runtime_precision_transport_ready();
  IF NEW.attempt>OLD.attempt OR NEW.state='leased' AND (OLD.state,OLD.lease_owner,OLD.lease_token) IS DISTINCT FROM (NEW.state,NEW.lease_owner,NEW.lease_token) OR NEW.state='exhausted' AND (OLD.state='failed' OR OLD.state='leased' AND OLD.lease_expires_at<=transaction_timestamp()) THEN
   IF NOT COALESCE(current_setting('zasp.runtime_precision_outbox_claim',true)='runtime-event-v2' AND zasp_discovery_principal_ready('zasp_outbox_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime precision outbox claim rejected';END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_precision_stage_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE source_value text;schema_value text;
BEGIN
 SELECT b.source_kind,b.payload_schema_version INTO source_value,schema_value FROM zasp_runtime_batch_authorities b WHERE (b.organization_id,b.workspace_id,b.environment_id,b.batch_id,b.batch_generation)=(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.batch_id,NEW.batch_generation);
 IF schema_value='runtime-event-v2' OR source_value='otlp' AND schema_value='runtime-event-v1' THEN
  IF NOT COALESCE(zasp_production_runtime_precision_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime precision authority unavailable';END IF;
  IF NOT COALESCE(CASE WHEN schema_value='runtime-event-v2' THEN (NEW.stage,NEW.stage_order,NEW.implementation_version) IN(('archive',1,'runtime-archive-v2'),('index',2,'runtime-index-v2'),('correlate',3,'runtime-correlation-v4'),('project',4,'runtime-projection-v3'),('complete',5,'runtime-complete-v3')) ELSE (NEW.stage,NEW.stage_order,NEW.implementation_version) IN(('archive',1,'runtime-archive-v1'),('index',2,'runtime-index-v1'),('correlate',3,'runtime-correlation-v3'),('project',4,'runtime-projection-v2'),('complete',5,'runtime-complete-v2')) END,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime precision stage tuple rejected';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_risk_mutate(requested_operation text, requested_finding_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_idempotency_key text, expected_version bigint, requested_status text, requested_reason text, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    requested_intent jsonb;
    digest_value bytea;
    prior_digest bytea;
    prior_response jsonb;
    result_version bigint;
    result_body jsonb;
BEGIN
    LOCK TABLE "public"."zasp_risk_findings", "public"."zasp_workflow_idempotency", "public"."zasp_workflow_audit", "public"."zasp_workflow_receipts" IN ROW EXCLUSIVE MODE;
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" release JOIN "public"."zasp_schema_metadata" marker ON marker."key"='production_core_schema' AND marker."value"='production-recovery-v1' WHERE release."version"=27 AND release."name"='production_recovery' AND NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" later WHERE later."version">50)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='risk projection release unavailable';
    END IF;
    IF requested_operation NOT IN ('updateFinding','acceptFindingRisk') OR expected_version<1
       OR length(requested_idempotency_key) NOT BETWEEN 16 AND 128
       OR requested_finding_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_principal_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_operation='updateFinding' AND (requested_status NOT IN ('open','under_review','resolved') OR requested_reason IS NOT NULL)
       OR requested_operation='acceptFindingRisk' AND (requested_status<>'accepted' OR length(requested_reason) NOT BETWEEN 1 AND 512) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid risk mutation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_risk_findings" AS candidate WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "public"."zasp_risk_finding_visible"(candidate)) THEN
        RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='risk finding missing';
    END IF;
    requested_intent := jsonb_build_object('resource_id',requested_finding_id,'expected_version',expected_version,'body',CASE WHEN requested_operation='updateFinding' THEN jsonb_build_object('status',requested_status) ELSE jsonb_build_object('reason',requested_reason) END);
    PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key),0));
    digest_value := digest(convert_to(requested_intent::text,'UTF8'),'sha256');
    SELECT "request_digest","response" INTO prior_digest,prior_response FROM "public"."zasp_workflow_idempotency"
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id
       AND "principal_id"=requested_principal_id AND "operation"=requested_operation AND "idempotency_key"=requested_idempotency_key;
    IF FOUND THEN
        IF prior_digest<>digest_value THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='idempotency conflict'; END IF;
        RETURN prior_response||jsonb_build_object('replayed',true);
    END IF;
    UPDATE "public"."zasp_risk_findings" AS candidate SET "status"=requested_status,"acceptance_reason"=CASE WHEN requested_operation='acceptFindingRisk' THEN requested_reason ELSE NULL END,"version"="version"+1,"updated_at"=transaction_timestamp()
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "version"=expected_version AND "public"."zasp_risk_finding_visible"(candidate)
     RETURNING "version" INTO result_version;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='risk finding version conflict'; END IF;
    result_body := "public"."zasp_risk_finding_get"(requested_finding_id,requested_organization_id,requested_workspace_id,requested_environment_id);
    prior_response := jsonb_build_object('body',result_body,'version',result_version,'audit_id',requested_audit_id,'correlation_id',requested_correlation_id,'replayed',false);
    IF requested_receipt_id IS NOT NULL THEN prior_response:=prior_response||jsonb_build_object('receipt_id',requested_receipt_id); END IF;
    INSERT INTO "public"."zasp_workflow_audit" ("organization_id","workspace_id","environment_id","audit_id","correlation_id","principal_id","operation","resource_kind","resource_id","resource_version") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_audit_id,requested_correlation_id,requested_principal_id,requested_operation,'finding',requested_finding_id,result_version);
    INSERT INTO "public"."zasp_workflow_idempotency" ("organization_id","workspace_id","environment_id","principal_id","operation","idempotency_key","request_digest","response","receipt_semantics") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key,digest_value,prior_response-'replayed',CASE WHEN requested_receipt_id IS NULL THEN 'receiptless_incompatible' ELSE 'receipt_backed' END);
    IF requested_receipt_id IS NOT NULL THEN
        INSERT INTO "public"."zasp_workflow_receipts" ("organization_id","workspace_id","environment_id","principal_id","receipt_id","operation","idempotency_key","intent","result","resource_kind","resource_id","resource_version","audit_id","correlation_id") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_receipt_id,requested_operation,requested_idempotency_key,requested_intent,result_body,'finding',requested_finding_id,result_version,requested_audit_id,requested_correlation_id);
    END IF;
    RETURN prior_response;
END;
$function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_ack_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, worker_value text, lease_token_value text, provider_ack_digest_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE delivery_row zasp_runtime_deliveries%ROWTYPE;result_value jsonb;
BEGIN
 IF NOT zasp_runtime_principal_ready('zasp_runtime_coordinator') OR octet_length(provider_ack_digest_value)<>32 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime delivery authority rejected';END IF;
 SELECT * INTO delivery_row FROM zasp_runtime_deliveries existing WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id,existing.batch_generation,existing.message_id,existing.message_digest)=(organization_value,workspace_value,environment_value,batch_value,generation_value,message_value,message_digest_value) FOR UPDATE;
 IF FOUND AND delivery_row.disposition='acked' AND delivery_row.provider_ack_digest=provider_ack_digest_value THEN RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','acked','replayed',true);END IF;
 IF NOT FOUND OR delivery_row.disposition<>'ack_pending' OR delivery_row.lease_owner<>worker_value OR delivery_row.lease_token<>lease_token_value OR delivery_row.lease_expires_at<=transaction_timestamp() OR delivery_row.visibility_deadline<=transaction_timestamp() OR NOT EXISTS(SELECT 1 FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) AND authority_row.state IN('succeeded','failed','quarantined') AND authority_row.completion_digest IS NOT NULL) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime delivery lease missing';END IF;
 UPDATE zasp_runtime_deliveries existing SET disposition='acked',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,visibility_deadline=NULL,provider_ack_digest=provider_ack_digest_value,updated_at=transaction_timestamp() WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','acked','replayed',false);
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_ack_outbox(topic_value text, organization_value text, workspace_value text, environment_value text, outbox_value text, worker_value text, lease_token_value text, provider_ack_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;remaining_count integer;
BEGIN
 IF topic_value<>'runtime-events' OR provider_ack_value !~ '^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid runtime outbox acknowledgement';END IF;
 IF NOT pg_has_role(session_user,'zasp_outbox_worker','MEMBER') AND NOT pg_has_role(session_user,'zasp_discovery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime outbox authority denied';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_discovery_outbox WHERE (organization_id,workspace_id,environment_id,id,topic)=(organization_value,workspace_value,environment_value,outbox_value,topic_value)) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime outbox lease missing';END IF;
 result:=zasp_discovery_ack_outbox(organization_value,workspace_value,environment_value,outbox_value,worker_value,lease_token_value,provider_ack_value);
 SELECT count(*) INTO remaining_count FROM zasp_discovery_outbox WHERE topic=topic_value AND state='leased' AND lease_owner=worker_value AND lease_token=lease_token_value AND lease_expires_at>transaction_timestamp();
 RETURN result||jsonb_build_object('remaining_count',remaining_count);
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_claim_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, receive_count_value integer, worker_value text, lease_token_value text, lease_seconds integer, visibility_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE batch_row zasp_runtime_batch_authorities%ROWTYPE;delivery_row zasp_runtime_deliveries%ROWTYPE;outbox_digest bytea;disposition_value text;replayed_value boolean:=false;lease_expires_value timestamptz;visibility_deadline_value timestamptz;
BEGIN
 IF NOT zasp_runtime_principal_ready('zasp_runtime_coordinator') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(batch_value) OR generation_value<1 OR message_value !~ '^[A-Za-z0-9_-]{1,128}$' OR octet_length(message_digest_value)<>32 OR receive_count_value NOT BETWEEN 1 AND 100 OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR visibility_seconds<lease_seconds OR visibility_seconds>43200 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime delivery authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'zasp-runtime-delivery',organization_value,workspace_value,environment_value,batch_value),0));
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 IF NOT FOUND OR batch_row.state='uploading' THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime delivery missing';END IF;
 SELECT outbox.payload_digest INTO outbox_digest FROM zasp_discovery_outbox outbox WHERE (outbox.organization_id,outbox.workspace_id,outbox.environment_id,outbox.topic,outbox.deterministic_key,outbox.payload_version)=(organization_value,workspace_value,environment_value,'runtime-events','runtime:'||batch_value,15);
 IF NOT FOUND OR outbox_digest IS DISTINCT FROM message_digest_value THEN
  IF batch_row.state NOT IN('succeeded','failed','unknown','quarantined') THEN UPDATE zasp_runtime_batch_authorities authority_row SET state='quarantined',completed_at=transaction_timestamp(),completion_digest=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,message_value,encode(message_digest_value,'hex'),'delivery-drift'),'UTF8'),'sha256'),completion_result=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'state','quarantined','error_class','malformed') WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value);END IF;
  RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','quarantined','replayed',false);
 END IF;
 SELECT * INTO delivery_row FROM zasp_runtime_deliveries existing WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value) FOR UPDATE;
 -- v36: exact durable outbox identity permits at-least-once publication.
 IF FOUND AND delivery_row.batch_generation=generation_value AND delivery_row.message_digest=message_digest_value AND delivery_row.message_id<>message_value THEN
  IF batch_row.state='unknown' OR delivery_row.disposition='unknown' THEN
   RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',true);
  END IF;
  IF batch_row.state IN('succeeded','failed','quarantined') THEN
   RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_terminal','replayed',true);
  END IF;
  IF delivery_row.disposition NOT IN('held','ack_pending') THEN
   RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',true);
  END IF;
  IF delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp() THEN
   RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_duplicate','replayed',true);
  END IF;
  UPDATE zasp_runtime_deliveries existing SET message_id=message_value,receive_count=receive_count_value,provider_ack_digest=NULL,lease_expires_at=transaction_timestamp()
   WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
  delivery_row.message_id:=message_value;delivery_row.receive_count:=receive_count_value;delivery_row.lease_expires_at:=transaction_timestamp();
 END IF;
 IF FOUND AND (delivery_row.batch_generation,delivery_row.message_id,delivery_row.message_digest) IS DISTINCT FROM (generation_value,message_value,message_digest_value) THEN
  UPDATE zasp_runtime_deliveries existing SET disposition='quarantined',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,visibility_deadline=NULL,updated_at=transaction_timestamp() WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
  UPDATE zasp_runtime_batch_authorities authority_row SET state='quarantined',completed_at=transaction_timestamp(),completion_digest=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,message_value,encode(message_digest_value,'hex'),'delivery-drift'),'UTF8'),'sha256'),completion_result=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'state','quarantined','error_class','malformed') WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value) AND authority_row.state NOT IN('succeeded','failed','unknown','quarantined');
  RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','quarantined','replayed',false);
 END IF;
 IF FOUND AND receive_count_value<delivery_row.receive_count THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime delivery conflict';END IF;
 IF FOUND AND delivery_row.disposition='acked' THEN RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_terminal','replayed',true);END IF;
 IF batch_row.state='unknown' OR FOUND AND delivery_row.disposition='unknown' THEN RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',FOUND);END IF;
 IF FOUND AND delivery_row.disposition IN('held','ack_pending') AND delivery_row.lease_expires_at>transaction_timestamp() AND (delivery_row.lease_owner,delivery_row.lease_token) IS DISTINCT FROM (worker_value,lease_token_value) THEN RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','busy','replayed',false,'lease_expires_at',delivery_row.lease_expires_at);END IF;
 IF EXISTS(SELECT 1 FROM zasp_runtime_deliveries other WHERE other.organization_id=organization_value AND other.batch_id<>batch_value AND other.disposition IN('held','ack_pending') AND other.lease_expires_at>transaction_timestamp()) THEN RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','busy','replayed',false);END IF;
 disposition_value:=CASE WHEN batch_row.state IN('succeeded','failed','quarantined') THEN 'ack_pending' ELSE 'held' END;
 lease_expires_value:=transaction_timestamp()+make_interval(secs=>lease_seconds);visibility_deadline_value:=transaction_timestamp()+make_interval(secs=>visibility_seconds);
 IF FOUND THEN
  replayed_value:=delivery_row.receive_count=receive_count_value AND delivery_row.disposition=disposition_value AND (delivery_row.lease_owner,delivery_row.lease_token) IS NOT DISTINCT FROM (worker_value,lease_token_value);
  UPDATE zasp_runtime_deliveries existing SET receive_count=GREATEST(existing.receive_count,receive_count_value),disposition=disposition_value,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=lease_expires_value,visibility_deadline=visibility_deadline_value,updated_at=transaction_timestamp() WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 ELSE
  INSERT INTO zasp_runtime_deliveries(organization_id,workspace_id,environment_id,batch_id,batch_generation,message_id,message_digest,receive_count,disposition,lease_owner,lease_token,lease_expires_at,visibility_deadline) VALUES(organization_value,workspace_value,environment_value,batch_value,generation_value,message_value,message_digest_value,receive_count_value,disposition_value,worker_value,lease_token_value,lease_expires_value,visibility_deadline_value);
 END IF;
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition',CASE WHEN disposition_value='held' THEN 'claimed' ELSE disposition_value END,'replayed',replayed_value,'lease_expires_at',lease_expires_value,'visibility_deadline',visibility_deadline_value,'artifact_reference',batch_row.raw_artifact_reference,'artifact_key',batch_row.raw_artifact_key,'artifact_version_id',batch_row.raw_artifact_version_id,'artifact_checksum',encode(batch_row.raw_artifact_checksum,'hex'),'artifact_size_bytes',batch_row.raw_artifact_size_bytes,'artifact_kms_key',batch_row.raw_artifact_kms_key,'request_digest',encode(batch_row.request_digest,'hex'));
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_claim_outbox(topic_value text, worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE response jsonb;last_organization text;claimed_last_organization text;
BEGIN
 IF topic_value<>'runtime-events' OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid runtime outbox claim';END IF;
 IF NOT pg_has_role(session_user,'zasp_outbox_worker','MEMBER') AND NOT pg_has_role(session_user,'zasp_discovery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime outbox authority denied';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp_runtime_outbox:'||topic_value,0));
 INSERT INTO zasp_discovery_outbox_topic_fairness(topic) VALUES(topic_value) ON CONFLICT(topic) DO NOTHING;
 SELECT last_organization_id INTO last_organization FROM zasp_discovery_outbox_topic_fairness WHERE topic=topic_value FOR UPDATE;
 UPDATE zasp_discovery_outbox SET state='exhausted',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_error=COALESCE(last_error,'maximum publish attempts exhausted')
 WHERE topic=topic_value AND attempt>=100 AND (state='failed' OR state='leased' AND lease_expires_at<=transaction_timestamp());
 WITH organizations AS (
  SELECT candidate.organization_id,min(candidate.available_at) due FROM zasp_discovery_outbox candidate
  WHERE candidate.topic=topic_value AND candidate.attempt<100 AND (candidate.state IN('pending','failed') OR candidate.state='leased' AND candidate.lease_expires_at<=transaction_timestamp()) AND candidate.available_at<=transaction_timestamp()
    AND NOT EXISTS(SELECT 1 FROM zasp_discovery_outbox live WHERE live.topic=topic_value AND live.organization_id=candidate.organization_id AND live.state='leased' AND live.lease_expires_at>transaction_timestamp())
  GROUP BY candidate.organization_id
 ),ordered_organizations AS (
  SELECT organization_id,due,row_number() OVER(ORDER BY CASE WHEN last_organization IS NULL OR organization_id>last_organization THEN 0 ELSE 1 END,organization_id) fair_order
  FROM organizations ORDER BY fair_order LIMIT claim_limit
 ),picked AS (
  SELECT chosen.ctid,chosen.organization_id,chosen.created_at,chosen.id,organization.fair_order FROM ordered_organizations organization
  CROSS JOIN LATERAL (
   SELECT outbox.ctid,outbox.organization_id,outbox.created_at,outbox.id FROM zasp_discovery_outbox outbox
   WHERE outbox.organization_id=organization.organization_id AND outbox.topic=topic_value AND outbox.attempt<100
     AND (outbox.state IN('pending','failed') OR outbox.state='leased' AND outbox.lease_expires_at<=transaction_timestamp()) AND outbox.available_at<=transaction_timestamp()
   ORDER BY outbox.created_at,outbox.id LIMIT 1 FOR UPDATE SKIP LOCKED
  ) chosen
 ),claimed AS (
  UPDATE zasp_discovery_outbox outbox SET state='leased',attempt=attempt+1,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),completion_digest=NULL,completion_result=NULL
  FROM (SELECT * FROM picked ORDER BY fair_order) candidate WHERE outbox.ctid=candidate.ctid
  RETURNING outbox.organization_id,outbox.workspace_id,outbox.environment_id,outbox.id,outbox.topic,outbox.deterministic_key,outbox.payload_version,outbox.payload,encode(outbox.payload_digest,'base64') payload_digest,outbox.attempt,outbox.lease_expires_at,candidate.fair_order
 )
 SELECT jsonb_build_object('items',COALESCE(jsonb_agg(to_jsonb(claimed)-'fair_order' ORDER BY fair_order),'[]'::jsonb)),(array_agg(organization_id ORDER BY fair_order DESC))[1] INTO response,claimed_last_organization FROM claimed;
 IF claimed_last_organization IS NOT NULL THEN UPDATE zasp_discovery_outbox_topic_fairness SET last_organization_id=claimed_last_organization,updated_at=transaction_timestamp() WHERE topic=topic_value;END IF;
 RETURN response;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_claim_reconciliation(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE response jsonb;
BEGIN
 UPDATE zasp_runtime_ingest_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
 IF NOT zasp_discovery_principal_ready('zasp_runtime_ingest') OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 60 AND 300 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime reconciliation claim rejected';END IF;
 UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state='succeeded',completion_worker='observed',completion_token_digest=digest(convert_to('observed','UTF8'),'sha256'),completion_digest=digest(convert_to(authority_row.completion_result::text,'UTF8'),'sha256'),completion_result=COALESCE(authority_row.completion_result,jsonb_build_object('batch_id',authority_row.batch_id,'generation',authority_row.batch_generation,'state',authority_row.state,'replayed',true)),completed_at=transaction_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL
 FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id) AND work_row.state NOT IN('succeeded','quarantined') AND authority_row.state NOT IN('uploading','unknown');
 UPDATE zasp_runtime_ingest_reconciliation_work SET state=CASE WHEN attempt>=100 THEN 'exhausted' ELSE 'retryable' END,available_at=transaction_timestamp(),last_error_code=CASE WHEN attempt>=100 THEN 'exhausted' ELSE 'outcome_unknown' END,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL WHERE state='leased' AND lease_expires_at<=transaction_timestamp();
 WITH candidates AS (
  SELECT work_row.ctid FROM zasp_runtime_ingest_reconciliation_work work_row JOIN zasp_runtime_batch_authorities authority_row USING(organization_id,workspace_id,environment_id,batch_id)
  WHERE work_row.state IN('pending','retryable') AND work_row.attempt<100 AND work_row.available_at<=transaction_timestamp() AND authority_row.state IN('uploading','unknown') ORDER BY work_row.available_at,work_row.organization_id,work_row.batch_id FOR UPDATE OF work_row SKIP LOCKED LIMIT claim_limit
 ),claimed AS (
  UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state='leased',attempt=work_row.attempt+1,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),last_error_code=NULL FROM candidates WHERE work_row.ctid=candidates.ctid
  RETURNING work_row.*
 ) SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',claimed.organization_id,'workspace_id',claimed.workspace_id,'environment_id',claimed.environment_id,'batch_id',claimed.batch_id,'generation',claimed.batch_generation,'attempt',claimed.attempt,'lease_expires_at',claimed.lease_expires_at,'request_digest',encode(authority_row.request_digest,'hex'),'artifact_key',authority_row.raw_artifact_key,'content_digest',encode(authority_row.content_digest,'hex'),'payload_size_bytes',authority_row.payload_size_bytes,'media_type',authority_row.payload_media_type,'schema_version',authority_row.payload_schema_version) ORDER BY claimed.organization_id,claimed.batch_id),'[]'::jsonb) INTO response FROM claimed JOIN zasp_runtime_batch_authorities authority_row USING(organization_id,workspace_id,environment_id,batch_id);
 RETURN response;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_claim_stage_compatible(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer, allow_v2 boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE stage_value text;authority_value text;result_value jsonb;prior_capability text;
BEGIN
 stage_value:=zasp_runtime_stage_for_session();
 IF worker_value IS NULL OR lease_token_value IS NULL OR lease_seconds IS NULL OR claim_limit IS NULL OR allow_v2 IS NULL OR (allow_v2 AND stage_value<>'correlate') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime routing capability rejected';END IF;
 authority_value:=CASE stage_value WHEN 'archive' THEN 'zasp_runtime_archive_worker' WHEN 'index' THEN 'zasp_runtime_index_worker' WHEN 'correlate' THEN 'zasp_runtime_correlation_worker' WHEN 'project' THEN 'zasp_runtime_projection_worker' WHEN 'complete' THEN 'zasp_runtime_coordinator' END;
 IF stage_value IS NULL OR NOT zasp_runtime_principal_ready(authority_value) OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime stage authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp-runtime-stage-claim:'||stage_value,0));
 prior_capability:=COALESCE(current_setting('zasp.runtime_correlation_claim_version',true),'');
 PERFORM set_config('zasp.runtime_correlation_claim_version',CASE WHEN allow_v2 THEN 'runtime-correlation-v2' ELSE 'runtime-correlation-v1' END,true);
 WITH exhausted AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='failed',last_error_class='exhausted',completed_at=transaction_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_heartbeat_at=NULL,
   completion_digest=digest(convert_to(concat_ws(chr(31),stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation::text,stage_row.stage,stage_row.attempt::text,'exhausted'),'UTF8'),'sha256'),
   completion_result=jsonb_build_object('batch_id',stage_row.batch_id,'generation',stage_row.batch_generation,'stage',stage_row.stage,'state','failed','attempt',stage_row.attempt,'error_class','exhausted')
  WHERE stage_row.stage=stage_value AND (stage_value NOT IN('project','complete') OR stage_value='project' AND stage_row.implementation_version='runtime-projection-v1' OR stage_value='complete' AND stage_row.implementation_version='runtime-complete-v1') AND (stage_value<>'correlate' OR stage_row.implementation_version='runtime-correlation-v1' OR allow_v2 AND stage_row.implementation_version='runtime-correlation-v2') AND stage_row.attempt>=100 AND stage_row.state IN('pending','retryable','leased') AND (stage_row.state<>'leased' OR stage_row.lease_expires_at<=transaction_timestamp())
  RETURNING stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.completion_digest,stage_row.completion_result
 ),failed_batches AS (
  UPDATE zasp_runtime_batch_authorities authority_row SET state='failed',completed_at=transaction_timestamp(),completion_digest=exhausted.completion_digest,completion_result=exhausted.completion_result
  FROM exhausted WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(exhausted.organization_id,exhausted.workspace_id,exhausted.environment_id,exhausted.batch_id)
  RETURNING authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.completion_digest,authority_row.completion_result
 ),failed_legacy_batches AS (
  UPDATE zasp_runtime_batches batch_row SET state='failed',completed_at=transaction_timestamp()
  FROM failed_batches WHERE (batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id)
  RETURNING batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id
 ),failed_jobs AS (
  UPDATE zasp_discovery_jobs job_row SET state='failed',last_error='exhausted',completed_at=transaction_timestamp(),updated_at=transaction_timestamp(),completion_digest=failed_batches.completion_digest,completion_result=failed_batches.completion_result
  FROM failed_batches WHERE (job_row.organization_id,job_row.workspace_id,job_row.environment_id,job_row.kind,job_row.authority_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,'runtime',failed_batches.batch_id)
  RETURNING job_row.organization_id
 )
 UPDATE zasp_runtime_deliveries delivery_row SET disposition='ack_pending',updated_at=transaction_timestamp()
 FROM failed_batches WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id) AND delivery_row.disposition='held';
 WITH eligible AS (
  SELECT stage_row.ctid row_id,stage_row.*,row_number() OVER(PARTITION BY stage_row.organization_id ORDER BY stage_row.available_at,stage_row.batch_id) organization_rank
  FROM zasp_runtime_stage_work stage_row
  WHERE stage_row.stage=stage_value AND (stage_value NOT IN('project','complete') OR stage_value='project' AND stage_row.implementation_version='runtime-projection-v1' OR stage_value='complete' AND stage_row.implementation_version='runtime-complete-v1') AND (stage_value<>'correlate' OR stage_row.implementation_version='runtime-correlation-v1' OR allow_v2 AND stage_row.implementation_version='runtime-correlation-v2') AND stage_row.attempt<100 AND stage_row.available_at<=transaction_timestamp() AND (stage_row.state IN('pending','retryable') OR stage_row.state='leased' AND stage_row.lease_expires_at<=transaction_timestamp())
   AND stage_row.input_digest IS NOT NULL
   AND EXISTS(SELECT 1 FROM zasp_runtime_deliveries delivery_row WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id,delivery_row.batch_generation,delivery_row.disposition)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation,'held') AND delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp())
   AND (stage_row.stage_order=1 OR EXISTS(SELECT 1 FROM zasp_runtime_stage_work predecessor WHERE (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order,predecessor.state,predecessor.effect_digest)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage_order-1,'succeeded',stage_row.predecessor_digest)))
   AND NOT EXISTS(SELECT 1 FROM zasp_runtime_stage_work live_row WHERE live_row.stage=stage_value AND live_row.organization_id=stage_row.organization_id AND live_row.state='leased' AND live_row.lease_expires_at>transaction_timestamp())
 ),organizations AS (
  SELECT eligible.organization_id,min(eligible.available_at) first_available,MAX(fairness.last_claimed_at) last_claimed_at
  FROM eligible LEFT JOIN zasp_runtime_stage_fairness fairness ON (fairness.stage,fairness.organization_id)=(stage_value,eligible.organization_id)
  WHERE eligible.organization_rank=1 GROUP BY eligible.organization_id
  ORDER BY MAX(fairness.last_claimed_at) NULLS FIRST,min(eligible.available_at),eligible.organization_id LIMIT claim_limit
 ),candidates AS (
  SELECT stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage
  FROM zasp_runtime_stage_work stage_row JOIN eligible ON stage_row.ctid=eligible.row_id JOIN organizations ON organizations.organization_id=eligible.organization_id
  WHERE eligible.organization_rank=1 ORDER BY organizations.last_claimed_at NULLS FIRST,organizations.first_available,stage_row.organization_id,stage_row.batch_id FOR UPDATE OF stage_row SKIP LOCKED
 ),claimed AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='leased',attempt=stage_row.attempt+1,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),last_heartbeat_at=transaction_timestamp(),last_error_class=NULL
  FROM candidates WHERE (stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage)=(candidates.organization_id,candidates.workspace_id,candidates.environment_id,candidates.batch_id,candidates.stage)
  RETURNING stage_row.*
 ),fairness AS (
  INSERT INTO zasp_runtime_stage_fairness(stage,organization_id,last_claimed_at) SELECT stage_value,claimed.organization_id,transaction_timestamp() FROM claimed
  ON CONFLICT(stage,organization_id) DO UPDATE SET last_claimed_at=excluded.last_claimed_at RETURNING organization_id
 )
 SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',claimed.organization_id,'workspace_id',claimed.workspace_id,'environment_id',claimed.environment_id,'batch_id',claimed.batch_id,'generation',claimed.batch_generation,'stage',claimed.stage,'attempt',claimed.attempt,'implementation_version',claimed.implementation_version,'predecessor_digest',CASE WHEN claimed.predecessor_digest IS NULL THEN NULL ELSE encode(claimed.predecessor_digest,'hex') END,'input_digest',encode(claimed.input_digest,'hex'),'input_reference',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_reference ELSE predecessor.result_reference END,'input_version_id',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_version_id ELSE predecessor.result_version_id END,'lease_expires_at',claimed.lease_expires_at) ORDER BY claimed.organization_id,claimed.batch_id),'[]'::jsonb) INTO result_value
 FROM claimed JOIN zasp_runtime_batch_authorities authority_row ON (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.batch_generation)
 LEFT JOIN zasp_runtime_stage_work predecessor ON (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.stage_order-1);
 IF stage_value='archive' AND jsonb_array_length(result_value)>0 THEN UPDATE zasp_runtime_batch_authorities authority_row SET state='processing' WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(result_value) item WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(item->>'organization_id',item->>'workspace_id',item->>'environment_id',item->>'batch_id'));END IF;
 PERFORM set_config('zasp.runtime_correlation_claim_version',prior_capability,true);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_claim_stage_sandbox_compatible(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer, allow_v3 boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE stage_value text;authority_value text;result_value jsonb;prior_capability text;
BEGIN
 stage_value:=zasp_runtime_stage_for_session();
 IF worker_value IS NULL OR lease_token_value IS NULL OR lease_seconds IS NULL OR claim_limit IS NULL OR allow_v3 IS NULL OR (allow_v3 AND stage_value<>'correlate') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime routing capability rejected';END IF;
 authority_value:=CASE stage_value WHEN 'archive' THEN 'zasp_runtime_archive_worker' WHEN 'index' THEN 'zasp_runtime_index_worker' WHEN 'correlate' THEN 'zasp_runtime_correlation_worker' WHEN 'project' THEN 'zasp_runtime_projection_worker' WHEN 'complete' THEN 'zasp_runtime_coordinator' END;
 IF stage_value IS NULL OR NOT zasp_runtime_principal_ready(authority_value) OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime stage authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp-runtime-stage-claim:'||stage_value,0));
 prior_capability:=COALESCE(current_setting('zasp.runtime_correlation_claim_version',true),'');
 PERFORM set_config('zasp.runtime_correlation_claim_version',CASE WHEN allow_v3 THEN 'runtime-correlation-v3' ELSE 'runtime-correlation-v1' END,true);
 WITH exhausted AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='failed',last_error_class='exhausted',completed_at=transaction_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_heartbeat_at=NULL,
   completion_digest=digest(convert_to(concat_ws(chr(31),stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation::text,stage_row.stage,stage_row.attempt::text,'exhausted'),'UTF8'),'sha256'),
   completion_result=jsonb_build_object('batch_id',stage_row.batch_id,'generation',stage_row.batch_generation,'stage',stage_row.stage,'state','failed','attempt',stage_row.attempt,'error_class','exhausted')
  WHERE stage_row.stage=stage_value AND (stage_value<>'correlate' OR stage_row.implementation_version='runtime-correlation-v1' OR allow_v3 AND stage_row.implementation_version IN('runtime-correlation-v2','runtime-correlation-v3')) AND stage_row.attempt>=100 AND stage_row.state IN('pending','retryable','leased') AND (stage_row.state<>'leased' OR stage_row.lease_expires_at<=transaction_timestamp())
  RETURNING stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.completion_digest,stage_row.completion_result
 ),failed_batches AS (
  UPDATE zasp_runtime_batch_authorities authority_row SET state='failed',completed_at=transaction_timestamp(),completion_digest=exhausted.completion_digest,completion_result=exhausted.completion_result
  FROM exhausted WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(exhausted.organization_id,exhausted.workspace_id,exhausted.environment_id,exhausted.batch_id)
  RETURNING authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.completion_digest,authority_row.completion_result
 ),failed_legacy_batches AS (
  UPDATE zasp_runtime_batches batch_row SET state='failed',completed_at=transaction_timestamp()
  FROM failed_batches WHERE (batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id)
  RETURNING batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id
 ),failed_jobs AS (
  UPDATE zasp_discovery_jobs job_row SET state='failed',last_error='exhausted',completed_at=transaction_timestamp(),updated_at=transaction_timestamp(),completion_digest=failed_batches.completion_digest,completion_result=failed_batches.completion_result
  FROM failed_batches WHERE (job_row.organization_id,job_row.workspace_id,job_row.environment_id,job_row.kind,job_row.authority_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,'runtime',failed_batches.batch_id)
  RETURNING job_row.organization_id
 )
 UPDATE zasp_runtime_deliveries delivery_row SET disposition='ack_pending',updated_at=transaction_timestamp()
 FROM failed_batches WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id) AND delivery_row.disposition='held';
 WITH eligible AS (
  SELECT stage_row.ctid row_id,stage_row.*,row_number() OVER(PARTITION BY stage_row.organization_id ORDER BY stage_row.available_at,stage_row.batch_id) organization_rank
  FROM zasp_runtime_stage_work stage_row
  WHERE stage_row.stage=stage_value AND (stage_value<>'correlate' OR stage_row.implementation_version='runtime-correlation-v1' OR allow_v3 AND stage_row.implementation_version IN('runtime-correlation-v2','runtime-correlation-v3')) AND stage_row.attempt<100 AND stage_row.available_at<=transaction_timestamp() AND (stage_row.state IN('pending','retryable') OR stage_row.state='leased' AND stage_row.lease_expires_at<=transaction_timestamp())
   AND stage_row.input_digest IS NOT NULL
   AND EXISTS(SELECT 1 FROM zasp_runtime_deliveries delivery_row WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id,delivery_row.batch_generation,delivery_row.disposition)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation,'held') AND delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp())
   AND (stage_row.stage_order=1 OR EXISTS(SELECT 1 FROM zasp_runtime_stage_work predecessor WHERE (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order,predecessor.state,predecessor.effect_digest)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage_order-1,'succeeded',stage_row.predecessor_digest)))
   AND NOT EXISTS(SELECT 1 FROM zasp_runtime_stage_work live_row WHERE live_row.stage=stage_value AND live_row.organization_id=stage_row.organization_id AND live_row.state='leased' AND live_row.lease_expires_at>transaction_timestamp())
 ),organizations AS (
  SELECT eligible.organization_id,min(eligible.available_at) first_available,MAX(fairness.last_claimed_at) last_claimed_at
  FROM eligible LEFT JOIN zasp_runtime_stage_fairness fairness ON (fairness.stage,fairness.organization_id)=(stage_value,eligible.organization_id)
  WHERE eligible.organization_rank=1 GROUP BY eligible.organization_id
  ORDER BY MAX(fairness.last_claimed_at) NULLS FIRST,min(eligible.available_at),eligible.organization_id LIMIT claim_limit
 ),candidates AS (
  SELECT stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage
  FROM zasp_runtime_stage_work stage_row JOIN eligible ON stage_row.ctid=eligible.row_id JOIN organizations ON organizations.organization_id=eligible.organization_id
  WHERE eligible.organization_rank=1 ORDER BY organizations.last_claimed_at NULLS FIRST,organizations.first_available,stage_row.organization_id,stage_row.batch_id FOR UPDATE OF stage_row SKIP LOCKED
 ),claimed AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='leased',attempt=stage_row.attempt+1,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),last_heartbeat_at=transaction_timestamp(),last_error_class=NULL
  FROM candidates WHERE (stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage)=(candidates.organization_id,candidates.workspace_id,candidates.environment_id,candidates.batch_id,candidates.stage)
  RETURNING stage_row.*
 ),fairness AS (
  INSERT INTO zasp_runtime_stage_fairness(stage,organization_id,last_claimed_at) SELECT stage_value,claimed.organization_id,transaction_timestamp() FROM claimed
  ON CONFLICT(stage,organization_id) DO UPDATE SET last_claimed_at=excluded.last_claimed_at RETURNING organization_id
 )
 SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',claimed.organization_id,'workspace_id',claimed.workspace_id,'environment_id',claimed.environment_id,'batch_id',claimed.batch_id,'generation',claimed.batch_generation,'stage',claimed.stage,'attempt',claimed.attempt,'implementation_version',claimed.implementation_version,'predecessor_digest',CASE WHEN claimed.predecessor_digest IS NULL THEN NULL ELSE encode(claimed.predecessor_digest,'hex') END,'input_digest',encode(claimed.input_digest,'hex'),'input_reference',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_reference ELSE predecessor.result_reference END,'input_version_id',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_version_id ELSE predecessor.result_version_id END,'lease_expires_at',claimed.lease_expires_at) ORDER BY claimed.organization_id,claimed.batch_id),'[]'::jsonb) INTO result_value
 FROM claimed JOIN zasp_runtime_batch_authorities authority_row ON (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.batch_generation)
 LEFT JOIN zasp_runtime_stage_work predecessor ON (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.stage_order-1);
 IF stage_value='archive' AND jsonb_array_length(result_value)>0 THEN UPDATE zasp_runtime_batch_authorities authority_row SET state='processing' WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(result_value) item WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(item->>'organization_id',item->>'workspace_id',item->>'environment_id',item->>'batch_id'));END IF;
 PERFORM set_config('zasp.runtime_correlation_claim_version',prior_capability,true);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_commit_reserved_batch(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, request_digest_value bytea, job_value text, outbox_value text, artifact_reference_value text, artifact_key_value text, artifact_version_value text, artifact_checksum_value bytea, artifact_size_value bigint, artifact_kms_key_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE batch_row zasp_runtime_batch_authorities%ROWTYPE;event_payload jsonb;result_value jsonb;
BEGIN
 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(batch_value) OR generation_value<1 OR octet_length(request_digest_value)<>32 OR NOT zasp_valid_product_id(job_value) OR NOT zasp_valid_product_id(outbox_value) OR NOT zasp_discovery_s3_object_reference(artifact_reference_value) OR length(artifact_key_value) NOT BETWEEN 32 AND 1024 OR right(artifact_reference_value,length(artifact_key_value)+1)<>'/'||artifact_key_value OR length(artifact_version_value) NOT BETWEEN 1 AND 1024 OR artifact_version_value<>btrim(artifact_version_value) OR octet_length(artifact_checksum_value)<>32 OR artifact_size_value NOT BETWEEN 1 AND 67108864 OR artifact_kms_key_value !~ '^arn:aws:kms:[a-z0-9-]+:[0-9]{12}:key/[A-Za-z0-9-]{8,128}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime batch rejected';END IF;
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation,authority_row.request_digest)=(organization_value,workspace_value,environment_value,batch_value,generation_value,request_digest_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime batch rejected';END IF;
 IF batch_row.state NOT IN('uploading','unknown') THEN
  IF batch_row.state IN('queued','processing','succeeded','failed','quarantined') AND (batch_row.raw_artifact_reference,batch_row.raw_artifact_key,batch_row.raw_artifact_version_id,batch_row.raw_artifact_checksum,batch_row.raw_artifact_size_bytes,batch_row.raw_artifact_kms_key) IS NOT DISTINCT FROM (artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value)
   AND EXISTS(SELECT 1 FROM zasp_discovery_jobs job_row WHERE (job_row.organization_id,job_row.workspace_id,job_row.environment_id,job_row.id,job_row.kind,job_row.authority_id)=(organization_value,workspace_value,environment_value,job_value,'runtime',batch_value))
   AND EXISTS(SELECT 1 FROM zasp_discovery_outbox outbox_row WHERE (outbox_row.organization_id,outbox_row.workspace_id,outbox_row.environment_id,outbox_row.id,outbox_row.topic,outbox_row.deterministic_key,outbox_row.payload_version)=(organization_value,workspace_value,environment_value,outbox_value,'runtime-events','runtime:'||batch_value,15))
  THEN RETURN jsonb_build_object('batch_id',batch_row.batch_id,'generation',batch_row.batch_generation,'state',batch_row.state,'replayed',true);END IF;
  RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime batch conflict';
 END IF;
 IF (batch_row.raw_artifact_key,batch_row.content_digest,batch_row.payload_size_bytes) IS DISTINCT FROM (artifact_key_value,artifact_checksum_value,artifact_size_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime batch conflict';END IF;
 INSERT INTO zasp_runtime_batches(organization_id,workspace_id,environment_id,id,sensor_id,idempotency_key,payload_digest,event_count,payload_reference,payload_size_bytes,payload_media_type,payload_schema_version)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id,batch_row.sensor_id,batch_row.idempotency_key,batch_row.content_digest,batch_row.event_count,artifact_reference_value,batch_row.payload_size_bytes,batch_row.payload_media_type,batch_row.payload_schema_version);
 INSERT INTO zasp_discovery_jobs(organization_id,workspace_id,environment_id,id,kind,authority_id,idempotency_key,request_digest)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,job_value,'runtime',batch_row.batch_id,batch_row.idempotency_key,batch_row.request_digest);
 INSERT INTO zasp_runtime_stage_work(organization_id,workspace_id,environment_id,batch_id,batch_generation,stage,stage_order,implementation_version,input_digest)
 SELECT batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id,batch_row.batch_generation,stage_value.stage,stage_value.stage_order,stage_value.version_value,CASE WHEN stage_value.stage_order=1 THEN batch_row.content_digest ELSE NULL END
 FROM (VALUES('archive',1,'runtime-archive-v1'),('index',2,'runtime-index-v1'),('correlate',3,'runtime-correlation-v2'),('project',4,'runtime-projection-v1'),('complete',5,'runtime-complete-v1')) stage_value(stage,stage_order,version_value);
 event_payload:=jsonb_build_object('batch_id',batch_row.batch_id,'job_id',job_value,'generation',batch_row.batch_generation,'pipeline_version',15,'artifact_reference',artifact_reference_value,'artifact_key',artifact_key_value,'artifact_version_id',artifact_version_value,'artifact_checksum',encode(artifact_checksum_value,'hex'),'artifact_size_bytes',artifact_size_value,'payload_media_type',batch_row.payload_media_type,'payload_schema_version',batch_row.payload_schema_version,'event_count',batch_row.event_count,'request_digest',encode(batch_row.request_digest,'hex'));
 INSERT INTO zasp_discovery_outbox(organization_id,workspace_id,environment_id,id,topic,deterministic_key,payload_version,payload,payload_digest)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,outbox_value,'runtime-events','runtime:'||batch_row.batch_id,15,event_payload,digest(convert_to(event_payload::text,'UTF8'),'sha256'));
 UPDATE zasp_runtime_batch_authorities authority_row SET raw_artifact_reference=artifact_reference_value,raw_artifact_version_id=artifact_version_value,raw_artifact_checksum=artifact_checksum_value,raw_artifact_size_bytes=artifact_size_value,raw_artifact_kms_key=artifact_kms_key_value,state='queued',finalized_at=transaction_timestamp() WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id);
 result_value:=jsonb_build_object('batch_id',batch_row.batch_id,'generation',batch_row.batch_generation,'state','queued','replayed',false);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_finish_reconciliation(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, lease_token_value text, job_value text, outbox_value text, artifact_reference_value text, artifact_key_value text, artifact_version_value text, artifact_checksum_value bytea, artifact_size_value bigint, artifact_kms_key_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE work_value zasp_runtime_ingest_reconciliation_work%ROWTYPE;result_value jsonb;completion_digest_value bytea;
BEGIN
 UPDATE zasp_runtime_ingest_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
 completion_digest_value:=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,worker_value,encode(digest(convert_to(lease_token_value,'UTF8'),'sha256'),'hex'),job_value,outbox_value,artifact_reference_value,artifact_key_value,artifact_version_value,encode(artifact_checksum_value,'hex'),artifact_size_value::text,artifact_kms_key_value),'UTF8'),'sha256');
 SELECT * INTO work_value FROM zasp_runtime_ingest_reconciliation_work work_row WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id,work_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime reconciliation finish rejected';END IF;
 IF work_value.state IN('succeeded','quarantined') THEN
  IF (work_value.completion_worker,work_value.completion_token_digest,work_value.completion_digest) IS DISTINCT FROM (worker_value,digest(convert_to(lease_token_value,'UTF8'),'sha256'),completion_digest_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime reconciliation finish conflict';END IF;
  RETURN work_value.completion_result||jsonb_build_object('replayed',true);
 END IF;
 IF (work_value.state,work_value.lease_owner,work_value.lease_token) IS DISTINCT FROM ('leased',worker_value,lease_token_value) OR work_value.lease_expires_at<=transaction_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime reconciliation finish rejected';END IF;
 result_value:=zasp_runtime_reconcile_batch(organization_value,workspace_value,environment_value,batch_value,generation_value,(SELECT authority_row.request_digest FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value)),job_value,outbox_value,artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value);
 UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state=CASE result_value->>'state' WHEN 'quarantined' THEN 'quarantined' ELSE 'succeeded' END,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,completion_worker=worker_value,completion_token_digest=digest(convert_to(lease_token_value,'UTF8'),'sha256'),completion_digest=completion_digest_value,completion_result=result_value,completed_at=transaction_timestamp() WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_heartbeat_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, worker_value text, lease_token_value text, lease_seconds integer, visibility_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE lease_expires_value timestamptz;visibility_deadline_value timestamptz;
BEGIN
 IF NOT zasp_runtime_principal_ready('zasp_runtime_coordinator') OR lease_seconds NOT BETWEEN 5 AND 900 OR visibility_seconds<lease_seconds OR visibility_seconds>43200 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime delivery authority rejected';END IF;
 lease_expires_value:=transaction_timestamp()+make_interval(secs=>lease_seconds);visibility_deadline_value:=transaction_timestamp()+make_interval(secs=>visibility_seconds);
 UPDATE zasp_runtime_deliveries delivery_row SET lease_expires_at=lease_expires_value,visibility_deadline=visibility_deadline_value,updated_at=transaction_timestamp()
  WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id,delivery_row.batch_generation,delivery_row.message_id,delivery_row.message_digest,delivery_row.lease_owner,delivery_row.lease_token)=(organization_value,workspace_value,environment_value,batch_value,generation_value,message_value,message_digest_value,worker_value,lease_token_value) AND delivery_row.disposition IN('held','ack_pending') AND delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp();
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime delivery lease missing';END IF;
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'lease_expires_at',lease_expires_value,'visibility_deadline',visibility_deadline_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_heartbeat_outbox(topic_value text, worker_value text, lease_token_value text, lease_seconds integer, expected_count integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE lease_expiration timestamptz;updated_count integer;
BEGIN
 IF topic_value<>'runtime-events' OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR expected_count NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid runtime outbox heartbeat';END IF;
 IF NOT pg_has_role(session_user,'zasp_outbox_worker','MEMBER') AND NOT pg_has_role(session_user,'zasp_discovery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime outbox authority denied';END IF;
 lease_expiration:=transaction_timestamp()+make_interval(secs=>lease_seconds);
 UPDATE zasp_discovery_outbox SET lease_expires_at=lease_expiration WHERE topic=topic_value AND state='leased' AND lease_owner=worker_value AND lease_token=lease_token_value AND lease_expires_at>transaction_timestamp();
 GET DIAGNOSTICS updated_count=ROW_COUNT;
 IF updated_count<>expected_count THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime outbox lease set conflict';END IF;
 RETURN jsonb_build_object('id',topic_value,'lease_expires_at',to_char(lease_expiration AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'remaining_count',updated_count);
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_lookup_acceptance(locator_value bytea, secret_value bytea, enrollment_value text, batch_value text, idempotency_value text, content_digest_value bytea, source_value text, media_value text, schema_value text, size_value bigint, count_value integer, job_value text, outbox_value text, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority jsonb;batch_row zasp_runtime_batch_authorities%ROWTYPE;scope_bytes bytea;expected_payload jsonb;response jsonb;now_value timestamptz;
BEGIN
 IF NOT COALESCE(zasp_discovery_principal_ready('zasp_runtime_ingest') AND zasp_production_runtime_acceptance_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime acceptance principal rejected';END IF;
 IF NOT COALESCE(octet_length(locator_value)=16 AND octet_length(secret_value)=32 AND enrollment_value ~ '^[0-9a-f]{64}$' AND zasp_valid_product_id(batch_value) AND length(idempotency_value) BETWEEN 16 AND 128 AND octet_length(content_digest_value)=32 AND source_value IN('tetragon','otlp') AND media_value='application/json' AND schema_value='runtime-event-v1' AND size_value BETWEEN 1 AND 67108864 AND count_value BETWEEN 1 AND 1000 AND zasp_valid_product_id(job_value) AND zasp_valid_product_id(outbox_value),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime acceptance input rejected';END IF;
 authority:=zasp_runtime_authenticate_sensor(locator_value,secret_value,'event-ingest');
 scope_bytes:=convert_to('zasp.sensor-enrollment.v1','UTF8')||decode('00','hex')||convert_to(authority->>'organization_id','UTF8')||decode('00','hex')||convert_to(authority->>'workspace_id','UTF8')||decode('00','hex')||convert_to(authority->>'environment_id','UTF8')||decode('00','hex')||convert_to(authority->>'sensor_id','UTF8');
 IF encode(digest(scope_bytes,'sha256'),'hex') IS DISTINCT FROM enrollment_value OR authority->>'sensor_kind' IS DISTINCT FROM source_value THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='runtime acceptance enrollment rejected';END IF;
 -- Do not wait on a batch while holding sensor authority. A worker may need
 -- that sensor lock; contention is a retry, never a reason to invert locks.
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities b WHERE (b.organization_id,b.workspace_id,b.environment_id,b.sensor_id,b.idempotency_key)=(authority->>'organization_id',authority->>'workspace_id',authority->>'environment_id',authority->>'sensor_id',idempotency_value) FOR SHARE NOWAIT;
 response:=jsonb_build_object('found',false);
 IF FOUND THEN
  IF (batch_row.batch_id,batch_row.content_digest,batch_row.source_kind,batch_row.payload_media_type,batch_row.payload_schema_version,batch_row.payload_size_bytes,batch_row.event_count) IS DISTINCT FROM (batch_value,content_digest_value,source_value,media_value,schema_value,size_value,count_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime acceptance conflict';END IF;
  IF batch_row.state NOT IN('uploading','unknown') THEN
   IF NOT COALESCE(batch_row.state IN('queued','processing','succeeded','failed','quarantined') AND batch_row.finalized_at IS NOT NULL AND batch_row.raw_artifact_checksum=content_digest_value AND batch_row.raw_artifact_size_bytes=size_value AND zasp_discovery_s3_object_reference(batch_row.raw_artifact_reference) AND right(batch_row.raw_artifact_reference,length(batch_row.raw_artifact_key)+1)='/'||batch_row.raw_artifact_key AND length(batch_row.raw_artifact_version_id) BETWEEN 1 AND 1024 AND batch_row.raw_artifact_version_id=btrim(batch_row.raw_artifact_version_id) AND batch_row.raw_artifact_kms_key ~ '^arn:aws:kms:[a-z0-9-]+:[0-9]{12}:key/[A-Za-z0-9-]{8,128}$',false) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime acceptance artifact rejected';END IF;
   expected_payload:=jsonb_build_object('batch_id',batch_row.batch_id,'job_id',job_value,'generation',batch_row.batch_generation,'pipeline_version',15,'artifact_reference',batch_row.raw_artifact_reference,'artifact_key',batch_row.raw_artifact_key,'artifact_version_id',batch_row.raw_artifact_version_id,'artifact_checksum',encode(batch_row.raw_artifact_checksum,'hex'),'artifact_size_bytes',batch_row.raw_artifact_size_bytes,'payload_media_type',batch_row.payload_media_type,'payload_schema_version',batch_row.payload_schema_version,'event_count',batch_row.event_count,'request_digest',encode(batch_row.request_digest,'hex'));
   IF NOT EXISTS(SELECT 1 FROM zasp_runtime_batches b WHERE (b.organization_id,b.workspace_id,b.environment_id,b.id,b.sensor_id,b.idempotency_key,b.payload_digest,b.event_count,b.payload_reference,b.payload_size_bytes,b.payload_media_type,b.payload_schema_version)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_value,batch_row.sensor_id,idempotency_value,content_digest_value,count_value,batch_row.raw_artifact_reference,size_value,media_value,schema_value))
   OR NOT EXISTS(SELECT 1 FROM zasp_discovery_jobs j WHERE (j.organization_id,j.workspace_id,j.environment_id,j.id,j.kind,j.authority_id,j.idempotency_key,j.request_digest)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,job_value,'runtime',batch_value,idempotency_value,batch_row.request_digest))
   OR NOT EXISTS(SELECT 1 FROM zasp_discovery_outbox o WHERE (o.organization_id,o.workspace_id,o.environment_id,o.id,o.topic,o.deterministic_key,o.payload_version,o.payload,o.payload_digest)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,outbox_value,'runtime-events','runtime:'||batch_value,15,expected_payload,digest(convert_to(expected_payload::text,'UTF8'),'sha256')))
   OR (SELECT count(*) FROM zasp_runtime_stage_work s WHERE (s.organization_id,s.workspace_id,s.environment_id,s.batch_id,s.batch_generation)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_value,batch_row.batch_generation) AND (s.stage,s.stage_order) IN(('archive',1),('index',2),('correlate',3),('project',4),('complete',5)))<>5
   THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime acceptance durable binding rejected';END IF;
   response:=jsonb_build_object('found',true,'batch_id',batch_row.batch_id,'generation',batch_row.batch_generation,'state',batch_row.state);
  END IF;
 END IF;
 -- Authentication locks are still held. Check wall time after the last query,
 -- not transaction start time, so lock waits cannot extend an expired token.
 IF NOT COALESCE(zasp_discovery_principal_ready('zasp_runtime_ingest') AND zasp_production_runtime_acceptance_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime acceptance principal expired';END IF;
 now_value:=clock_timestamp();
 IF NOT EXISTS(SELECT 1 FROM zasp_sensor_tokens t JOIN zasp_sensors s ON (s.organization_id,s.workspace_id,s.environment_id,s.id,s.version)=(t.organization_id,t.workspace_id,t.environment_id,t.sensor_id,t.sensor_version_at_issue) WHERE (t.organization_id,t.workspace_id,t.environment_id,t.sensor_id,t.id,t.token_generation)=(authority->>'organization_id',authority->>'workspace_id',authority->>'environment_id',authority->>'sensor_id',authority->>'token_id',(authority->>'token_generation')::bigint) AND t.revoked_at IS NULL AND t.expires_at>now_value AND s.state IN('pending','active','degraded')) THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='runtime acceptance credential expired';END IF;
 RETURN response;
END
$function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_quarantine_reconciliation(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, lease_token_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE work_value zasp_runtime_ingest_reconciliation_work%ROWTYPE;batch_value_row zasp_runtime_batch_authorities%ROWTYPE;completion_digest_value bytea;result_value jsonb;
BEGIN
 UPDATE zasp_runtime_ingest_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
 completion_digest_value:=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,worker_value,encode(digest(convert_to(lease_token_value,'UTF8'),'sha256'),'hex'),'artifact_drift'),'UTF8'),'sha256');
 SELECT * INTO work_value FROM zasp_runtime_ingest_reconciliation_work work_row WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id,work_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime reconciliation quarantine rejected';END IF;
 IF work_value.state='quarantined' THEN
  IF (work_value.completion_worker,work_value.completion_token_digest,work_value.completion_digest) IS DISTINCT FROM (worker_value,digest(convert_to(lease_token_value,'UTF8'),'sha256'),completion_digest_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime reconciliation quarantine conflict';END IF;
  RETURN work_value.completion_result||jsonb_build_object('replayed',true);
 END IF;
 IF (work_value.state,work_value.lease_owner,work_value.lease_token) IS DISTINCT FROM ('leased',worker_value,lease_token_value) OR work_value.lease_expires_at<=transaction_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime reconciliation quarantine rejected';END IF;
 SELECT * INTO batch_value_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 IF NOT FOUND OR batch_value_row.state NOT IN('uploading','unknown') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime reconciliation quarantine rejected';END IF;
 result_value:=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'state','quarantined','error_class','artifact_drift','replayed',false);
 UPDATE zasp_runtime_batch_authorities authority_row SET state='quarantined',completed_at=transaction_timestamp(),completion_digest=completion_digest_value,completion_result=result_value WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state='quarantined',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,completion_worker=worker_value,completion_token_digest=digest(convert_to(lease_token_value,'UTF8'),'sha256'),completion_digest=completion_digest_value,completion_result=result_value,completed_at=transaction_timestamp(),last_error_code=NULL WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_release_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, worker_value text, lease_token_value text, outcome_value text, error_class_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE completion_digest_value bytea;result_value jsonb;
BEGIN
 IF NOT zasp_runtime_principal_ready('zasp_runtime_coordinator') OR outcome_value NOT IN('retryable','unknown','quarantined') OR outcome_value='retryable' AND error_class_value<>'retryable' OR outcome_value='unknown' AND error_class_value<>'outcome_unknown' OR outcome_value='quarantined' AND error_class_value NOT IN('denied','malformed') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime delivery authority rejected';END IF;
 completion_digest_value:=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,message_value,encode(message_digest_value,'hex'),worker_value,lease_token_value,outcome_value,error_class_value),'UTF8'),'sha256');
 result_value:=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition',outcome_value,'error_class',error_class_value);
 UPDATE zasp_runtime_deliveries delivery_row SET disposition=CASE WHEN outcome_value='retryable' THEN 'held' ELSE outcome_value END,lease_expires_at=CASE WHEN outcome_value='retryable' THEN transaction_timestamp() ELSE NULL END,visibility_deadline=CASE WHEN outcome_value='retryable' THEN transaction_timestamp() ELSE NULL END,lease_owner=CASE WHEN outcome_value='retryable' THEN delivery_row.lease_owner ELSE NULL END,lease_token=CASE WHEN outcome_value='retryable' THEN delivery_row.lease_token ELSE NULL END,updated_at=transaction_timestamp()
  WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id,delivery_row.batch_generation,delivery_row.message_id,delivery_row.message_digest,delivery_row.disposition,delivery_row.lease_owner,delivery_row.lease_token)=(organization_value,workspace_value,environment_value,batch_value,generation_value,message_value,message_digest_value,'held',worker_value,lease_token_value) AND delivery_row.lease_expires_at>transaction_timestamp();
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime delivery lease missing';END IF;
 IF outcome_value IN('unknown','quarantined') THEN UPDATE zasp_runtime_batch_authorities authority_row SET state=outcome_value,completed_at=transaction_timestamp(),completion_digest=completion_digest_value,completion_result=result_value WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value);END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_release_reconciliation(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, lease_token_value text, delay_seconds integer, error_code_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 UPDATE zasp_runtime_ingest_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
 IF delay_seconds NOT BETWEEN 5 AND 300 OR error_code_value NOT IN('not_found','dependency_unavailable','outcome_unknown') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime reconciliation release rejected';END IF;
 UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state=CASE WHEN work_row.attempt>=100 THEN 'exhausted' ELSE 'retryable' END,available_at=transaction_timestamp()+make_interval(secs=>delay_seconds),last_error_code=CASE WHEN work_row.attempt>=100 THEN 'exhausted' ELSE error_code_value END,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL
 WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id,work_row.batch_generation,work_row.lease_owner,work_row.lease_token)=(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,lease_token_value) AND work_row.state='leased' AND work_row.lease_expires_at>transaction_timestamp()
 RETURNING jsonb_build_object('batch_id',work_row.batch_id,'generation',work_row.batch_generation,'state',work_row.state,'attempt',work_row.attempt,'error_code',work_row.last_error_code,'replayed',false) INTO result_value;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime reconciliation release rejected';END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_retry_outbox(topic_value text, organization_value text, workspace_value text, environment_value text, outbox_value text, worker_value text, lease_token_value text, retry_after_seconds integer, error_code_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;remaining_count integer;
BEGIN
 IF topic_value<>'runtime-events' OR retry_after_seconds NOT BETWEEN 1 AND 3600 OR error_code_value<>'queue_publish_unknown' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid runtime outbox retry';END IF;
 IF NOT pg_has_role(session_user,'zasp_outbox_worker','MEMBER') AND NOT pg_has_role(session_user,'zasp_discovery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime outbox authority denied';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_discovery_outbox WHERE (organization_id,workspace_id,environment_id,id,topic)=(organization_value,workspace_value,environment_value,outbox_value,topic_value)) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime outbox lease missing';END IF;
 result:=zasp_discovery_retry_outbox(organization_value,workspace_value,environment_value,outbox_value,worker_value,lease_token_value,retry_after_seconds,error_code_value);
 SELECT count(*) INTO remaining_count FROM zasp_discovery_outbox WHERE topic=topic_value AND state='leased' AND lease_owner=worker_value AND lease_token=lease_token_value AND lease_expires_at>transaction_timestamp();
 RETURN result||jsonb_build_object('remaining_count',remaining_count);
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_workflow_mutate(mutation text, requested_kind text, requested_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_operation text, requested_idempotency_key text, expected_version bigint, requested_intent jsonb, requested_body jsonb, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    mutation_response jsonb;
    existing_receipt_id text;
BEGIN
    LOCK TABLE "public"."zasp_workflow_idempotency" IN ROW EXCLUSIVE MODE;
    IF NOT EXISTS (
        SELECT 1
          FROM "public"."zasp_schema_versions" AS release
          JOIN "public"."zasp_schema_metadata" AS schema_marker
            ON schema_marker."key" = 'production_core_schema'
           AND schema_marker."value" = 'production-recovery-v1'
         WHERE release."version" = 27
           AND release."name" = 'production_recovery'
           AND NOT EXISTS (
               SELECT 1 FROM "public"."zasp_schema_versions" AS later_release
                WHERE later_release."version" > 50
           )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance release unavailable';
    END IF;
    IF requested_receipt_id IS NOT NULL AND requested_receipt_id <> '' AND length(requested_receipt_id) > 128 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'invalid workflow receipt';
    END IF;
    mutation_response := "public"."zasp_workflow_mutate_v3"(
        mutation, requested_kind, requested_id,
        requested_organization_id, requested_workspace_id, requested_environment_id,
        requested_principal_id, requested_operation, requested_idempotency_key,
        expected_version, requested_intent, requested_body, requested_audit_id, requested_correlation_id
    );
    existing_receipt_id := mutation_response ->> 'receipt_id';
    IF existing_receipt_id IS NOT NULL THEN
        RETURN mutation_response;
    END IF;
    IF requested_receipt_id IS NULL OR requested_receipt_id = '' THEN
        UPDATE "public"."zasp_workflow_idempotency"
           SET "receipt_semantics" = 'receiptless_incompatible'
         WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
           AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
           AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key
           AND NULLIF("response" ->> 'receipt_id', '') IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
        END IF;
        RETURN mutation_response;
    END IF;
    INSERT INTO "public"."zasp_workflow_receipts" (
        "organization_id", "workspace_id", "environment_id", "principal_id", "receipt_id",
        "operation", "idempotency_key", "intent", "result", "resource_kind", "resource_id",
        "resource_version", "audit_id", "correlation_id"
    ) VALUES (
        requested_organization_id, requested_workspace_id, requested_environment_id, requested_principal_id, requested_receipt_id,
        requested_operation, requested_idempotency_key, requested_intent, mutation_response -> 'body', requested_kind, requested_id,
        (mutation_response ->> 'version')::bigint, mutation_response ->> 'audit_id', mutation_response ->> 'correlation_id'
    );
    mutation_response := mutation_response || jsonb_build_object('receipt_id', requested_receipt_id);
    UPDATE "public"."zasp_workflow_idempotency"
       SET "response" = mutation_response - 'replayed',
           "receipt_semantics" = 'receipt_backed'
     WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
       AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
       AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
    END IF;
    RETURN mutation_response;
END;
$function$

