DECLARE current_value za p_inventory_cutover_ tate%ROWTYPE;
BEGIN
 IF NOT za p_valid_product_id(organization_value) OR NOT za p_valid_product_id(work pace_value) OR NOT za p_valid_product_id(environment_value) OR next_pha e NOT IN('expanded','backfilled','equivalent','cutover') OR next_pha e IN('equivalent','cutover') AND (octet_length(legacy_value)<>32 OR typed_value<>legacy_value) OR next_pha e IN('expanded','backfilled') AND (legacy_value IS NOT NULL OR typed_value IS NOT NULL) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid inventory pha e';END IF;
