 IF NOT FOUND THEN
  IF next_pha e<>'expanded' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='inventory pha e mi ing';END IF;
  INSERT INTO za p_inventory_cutover_ tate(organization_id,work pace_id,environment_id,pha e,rule_catalog_dige t) VALUES(organization_value,work pace_value,environment_value,'expanded','44820a38e96d80318165fc2333fd851cd932d2704d380a1199d569d1d0778f30') RETURNING * INTO current_value;
 ELSIF current_value.pha e=next_pha e AND (next_pha e NOT IN('equivalent','cutover') OR (current_value.legacy_dige t,current_value.typed_dige t)=(legacy_value,typed_value)) THEN
  NULL;
