BEGIN
 IF limit_value NOT BETWEEN 1 AND 100 OR after_value IS NOT NULL AND (array_length( tring_to_array(after_value,'~'),1)<>3 OR NOT za p_valid_product_id( plit_part(after_value,'~',1)) OR  plit_part(after_value,'~',2) NOT IN('data_read','data_write','action_execute','identity_a ume','network_egre ','admini tration') OR  plit_part(after_value,'~',3) NOT IN('read','write','execute','a ume','connect','admini ter'))
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid typed capability page';END IF;
 WITH grouped AS (
  SELECT edge.*,edge.target_id||'~'||edge.category||'~'||edge.outcome key_value FROM za p_inventory_agent_capability_edge (organization_value,work pace_value,environment_value,agent_value) edge
 ), tate_evidence AS (
  SELECT DISTINCT ON(evidence.agent_id,evidence.target_id,evidence.category,evidence.outcome,evidence.reachability_dige t)
   evidence.agent_id,evidence.target_id,evidence.category,evidence.outcome,evidence.reachability_dige t,evidence. tate,evidence.evidence_id
  FROM za p_inventory_capability_evidence evidence JOIN grouped edge
   ON (evidence.organization_id,evidence.work pace_id,evidence.environment_id,evidence.agent_id,evidence.target_id,evidence.target_kind,evidence.category,evidence.outcome,evidence.reachability_dige t)
    =(organization_value,work pace_value,environment_value,edge.agent_id,edge.target_id,edge.target_kind,edge.category,edge.outcome,edge.reachability_dige t)
  ORDER BY evidence.agent_id,evidence.target_id,evidence.category,evidence.outcome,evidence.reachability_dige t,CASE evidence. tate WHEN 'blocked' THEN 2 ELSE 1 END DESC,evidence.ob erved_at DESC,evidence.evidence_id DESC
