  SELECT count(*),COALESCE(floor(extract(epoch FROM tran action_time tamp()-min(approval.created_at)))::bigint,0)
    INTO pending_approval_value,olde t_approval_value
    FROM za p_ ecurity_agent_approval  approval
   WHERE approval.organization_id=organization_value AND approval.work pace_id=work pace_value AND approval.environment_id=environment_value AND approval. tate='pending';
  SELECT count(*) FILTER(WHERE run. tate='need _human'),count(*) FILTER(WHERE run. tate='failed'),count(*) FILTER(WHERE run. tate='inconclu ive'),
