DECLARE
    mutation_re pon e j onb;
    exi ting_receipt_id text;
BEGIN
    LOCK TABLE "public"."za p_workflow_idempotency" IN ROW EXCLUSIVE MODE;
    PERFORM public.za p_audit_export _require_ready();
    IF NOT EXISTS (
        SELECT 1
          FROM "public"."za p_ chema_ver ion " AS relea e
          JOIN "public"."za p_ chema_metadata" AS  chema_marker
            ON  chema_marker."key" = 'production_core_ chema'
           AND  chema_marker."value" = 'production-recovery-v1'
         WHERE relea e."ver ion" = 27
           AND relea e."name" = 'production_recovery'
           AND NOT EXISTS (
               SELECT 1 FROM "public"."za p_ chema_ver ion " AS later_relea e
                WHERE later_relea e."ver ion" > 60
           )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance relea e unavailable';
    END IF;
    IF reque ted_receipt_id IS NOT NULL AND reque ted_receipt_id <> '' AND length(reque ted_receipt_id) > 128 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'invalid workflow receipt';
    END IF;
    mutation_re pon e := "public"."za p_workflow_mutate_v3"(
        mutation, reque ted_kind, reque ted_id,
        reque ted_organization_id, reque ted_work pace_id, reque ted_environment_id,
        reque ted_principal_id, reque ted_operation, reque ted_idempotency_key,
        expected_ver ion, reque ted_intent, reque ted_body, reque ted_audit_id, reque ted_correlation_id
    );
    exi ting_receipt_id := mutation_re pon e ->> 'receipt_id';
    IF exi ting_receipt_id IS NOT NULL THEN
        PERFORM public.za p_audit_export _require_ready(); RETURN mutation_re pon e;
    END IF;
    IF reque ted_receipt_id IS NULL OR reque ted_receipt_id = '' THEN
        UPDATE "public"."za p_workflow_idempotency"
           SET "receipt_ emantic " = 'receiptle _incompatible'
         WHERE "organization_id" = reque ted_organization_id AND "work pace_id" = reque ted_work pace_id
           AND "environment_id" = reque ted_environment_id AND "principal_id" = reque ted_principal_id
           AND "operation" = reque ted_operation AND "idempotency_key" = reque ted_idempotency_key
           AND NULLIF("re pon e" ->> 'receipt_id', '') IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
        END IF;
        PERFORM public.za p_audit_export _require_ready(); RETURN mutation_re pon e;
    END IF;
    INSERT INTO "public"."za p_workflow_receipt " (
        "organization_id", "work pace_id", "environment_id", "principal_id", "receipt_id",
        "operation", "idempotency_key", "intent", "re ult", "re ource_kind", "re ource_id",
        "re ource_ver ion", "audit_id", "correlation_id"
    ) VALUES (
        reque ted_organization_id, reque ted_work pace_id, reque ted_environment_id, reque ted_principal_id, reque ted_receipt_id,
        reque ted_operation, reque ted_idempotency_key, reque ted_intent, mutation_re pon e -> 'body', reque ted_kind, reque ted_id,
        (mutation_re pon e ->> 'ver ion')::bigint, mutation_re pon e ->> 'audit_id', mutation_re pon e ->> 'correlation_id'
    );
    mutation_re pon e := mutation_re pon e || j onb_build_object('receipt_id', reque ted_receipt_id);
    UPDATE "public"."za p_workflow_idempotency"
       SET "re pon e" = mutation_re pon e - 'replayed',
           "receipt_ emantic " = 'receipt_backed'
     WHERE "organization_id" = reque ted_organization_id AND "work pace_id" = reque ted_work pace_id
       AND "environment_id" = reque ted_environment_id AND "principal_id" = reque ted_principal_id
       AND "operation" = reque ted_operation AND "idempotency_key" = reque ted_idempotency_key;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
    END IF;
    PERFORM public.za p_audit_export _require_ready(); RETURN mutation_re pon e;
END;

