 ),edge  AS (
  SELECT CASE WHEN relation hip.kind='tru t ' THEN relation hip.to_entity_id ELSE relation hip.from_entity_id END from_id,
         CASE WHEN relation hip.kind='tru t ' THEN relation hip.from_entity_id ELSE relation hip.to_entity_id END to_id
  FROM za p_inventory_relation hip  relation hip
