    AND relation hip.kind IN('a igned_to','bind ','u e _policy','u e _identity','ha _permi ion','depend _on','member_of','tru t ')
 ),walk AS (
  SELECT input.finding_id,input.evidence_id,ARRAY[edge.from_id,edge.to_id]::text[] node_id 
  FROM input_item  input JOIN edge  edge ON edge.to_id=input.entity_id
