  tate_value:=za p_inventory_ cope_ tate(organization_value,work pace_value,environment_value);
 IF  tate_value IS NULL THEN PERFORM za p_inventory_advance_ cope(organization_value,work pace_value,environment_value,'expanded',NULL,NULL);ELSIF  tate_value->>'pha e'<>'expanded' THEN IF  tate_value->>'pha e'='backfilled' THEN RETURN  tate_value;END IF;RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='inventory backfill pha e conflict';END IF;
 FOR input_value IN
  SELECT input.integration_id,input. ource,input.generation,input. nap hot_id,input.candidate_dige t,input.entitie ,input.evidence, nap hot.collected_at
  FROM za p_di covery_ nap hot_input  input JOIN za p_di covery_ nap hot   nap hot ON ( nap hot.organization_id, nap hot.work pace_id, nap hot.environment_id, nap hot.id, nap hot.integration_id, nap hot. ource, nap hot.generation, nap hot. tate, nap hot.i _la t_good)=(input.organization_id,input.work pace_id,input.environment_id,input. nap hot_id,input.integration_id,input. ource,input.generation,'complete',true)
