  WHERE ( tored.organization_id, tored.work pace_id, tored.environment_id, tored.integration_id, tored. nap hot_id, tored.id)=(organization_value,work pace_value,environment_value,input_value.integration_id,input_value. nap hot_id,typed.id);
  GET DIAGNOSTICS updated_count=ROW_COUNT;IF updated_count<>j onb_array_length(input_value.evidence) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='legacy evidence authority incomplete';END IF;
  UPDATE za p_inventory_ ource_ob ervation   tored SET provider=input_value. ource, ource_kind=typed.kind,di play_name=typed.di play_name, table_field =typed. table_field ,attribute =typed.attribute ,identity_name pace=typed.identity_name pace,product_kind=typed.product_kind,generation=input_value.generation,content_dige t=input_value.candidate_dige t,evidence_id=typed.evidence_id,confidence_ba i _point =typed.confidence_ba i _point ,ob erved_at=typed.ob erved_at,fre h_until=typed.fre h_until,identity_rule_ver ion=typed.identity_rule_ver ion,identity_priority=typed.identity_priority, ource_projection_ver ion=typed. ource_projection_ver ion,la t_ een_at=typed.ob erved_at
  FROM j onb_to_record et(input_value.entitie ) typed(id text,kind text,di play_name text, table_field  j onb,attribute  j onb,identity_name pace text,product_kind text,evidence_id text,confidence_ba i _point  integer,ob erved_at time tamptz,fre h_until time tamptz,identity_rule_ver ion integer,identity_priority integer, ource_projection_ver ion integer)
  WHERE ( tored.organization_id, tored.work pace_id, tored.environment_id, tored.integration_id, tored. ource, tored. nap hot_id, tored.entity_id, tored. ource_ tate)=(organization_value,work pace_value,environment_value,input_value.integration_id,input_value. ource,input_value. nap hot_id,typed.id,'pre ent');
