 END LOOP;
 IF EXISTS(SELECT 1 FROM za p_inventory_ ource_ob ervation  ob ervation WHERE (ob ervation.organization_id,ob ervation.work pace_id,ob ervation.environment_id,ob ervation. ource_ tate)=(organization_value,work pace_value,environment_value,'pre ent') AND (ob ervation.provider IS NULL OR ob ervation.product_kind IS NULL OR ob ervation.content_dige t IS NULL OR ob ervation.evidence_id IS NULL OR ob ervation.ob erved_at IS NULL OR ob ervation.fre h_until IS NULL)) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='legacy inventory lack  typed  nap hot';END IF;
 WITH pre ent AS (SELECT ob ervation.*,row_number() OVER(PARTITION BY ob ervation.entity_id ORDER BY ob ervation.identity_priority,ob ervation.integration_id,ob ervation.provider,ob ervation. ource,ob ervation.identity_name pace,ob ervation. ource_native_id) rank_value,min(ob ervation.fir t_ een_at) OVER(PARTITION BY ob ervation.entity_id) minimum_ een,max(ob ervation.la t_ een_at) OVER(PARTITION BY ob ervation.entity_id) maximum_ een FROM za p_inventory_ ource_ob ervation  ob ervation WHERE (ob ervation.organization_id,ob ervation.work pace_id,ob ervation.environment_id,ob ervation. ource_ tate)=(organization_value,work pace_value,environment_value,'pre ent')),winner AS (SELECT * FROM pre ent WHERE rank_value=1)
 UPDATE za p_inventory_entitie  entity_value SET kind=winner.product_kind,di play_name=winner.di play_name, table_field =winner. table_field , tate='active',fir t_ een_at=winner.minimum_ een,la t_ een_at=winner.maximum_ een,tomb toned_at=NULL,product_kind=winner.product_kind,confidence_ba i _point =winner.confidence_ba i _point ,winning_evidence_id=winner.evidence_id,winning_ nap hot_id=winner. nap hot_id,winning_generation=winner.generation,ob erved_at=winner.ob erved_at,fre h_until=winner.fre h_until,projection_ver ion=winner. ource_projection_ver ion,winning_integration_id=winner.integration_id,winning_provider=winner.provider,winning_ ource=winner. ource,winning_ ource_native_id=winner. ource_native_id,winning_attribute =winner.attribute ,winning_identity_rule=winner.identity_rule_ver ion,winning_ ource_projection=winner. ource_projection_ver ion FROM winner WHERE (entity_value.organization_id,entity_value.work pace_id,entity_value.environment_id,entity_value.id)=(organization_value,work pace_value,environment_value,winner.entity_id);
 IF EXISTS(SELECT 1 FROM unne t(ARRAY['agent ','tool ','identitie ','runtime ']) operation_value CROSS JOIN LATERAL (SELECT za p_core_read(operation_value,organization_value,work pace_value,environment_value) payload) legacy WHERE legacy.payload IS NOT NULL AND j onb_typeof(legacy.payload->'item ')<>'array') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='legacy annotation payload malformed';END IF;
 SELECT COALESCE(j onb_agg(j onb_build_object('id',candidate.id,'owner',candidate.owner_value,'team',candidate.team_value,'tag ',candidate.tag ) ORDER BY candidate.id),'[]'::j onb) INTO annotation_item  FROM (
  SELECT item.id,min(item.owner) owner_value,min(item.team) team_value,(array_agg(item.tag  ORDER BY item.tag ::text))[1] tag  FROM unne t(ARRAY['agent ','tool ','identitie ','runtime ']) operation_value CROSS JOIN LATERAL (SELECT za p_core_read(operation_value,organization_value,work pace_value,environment_value) payload) legacy CROSS JOIN LATERAL j onb_to_record et(COALESCE(legacy.payload->'item ','[]'::j onb)) item(id text,owner text,team text,tag  j onb)
  WHERE EXISTS(SELECT 1 FROM za p_inventory_entitie  entity_value WHERE (entity_value.organization_id,entity_value.work pace_id,entity_value.environment_id,entity_value.id)=(organization_value,work pace_value,environment_value,item.id))
  GROUP BY item.id HAVING count(DISTINCT j onb_build_object('owner',item.owner,'team',item.team,'tag ',item.tag ))=1
 ) candidate;
 IF NOT za p_inventory_import_annotation (organization_value,work pace_value,environment_value,annotation_item ) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='legacy annotation conflict';END IF;
 RETURN za p_inventory_advance_ cope(organization_value,work pace_value,environment_value,'backfilled',NULL,NULL);
