DECLARE input_row za p_di covery_ nap hot_input %ROWTYPE;current_row za p_di covery_ri k_projection_current%ROWTYPE;canonical_item  j onb;expected_item  j onb; tored_item  j onb;finding_item  j onb;content_dige t_value bytea;item_count_value integer;replayed_value boolean:=fal e;
BEGIN
 IF NOT pg_ha _role( e ion_u er,'za p_projection_ri k_worker','MEMBER') AND NOT pg_ha _role( e ion_u er,'za p_di covery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ri k projection authority denied';END IF;
 IF NOT za p_valid_product_id( nap hot_value) OR NOT za p_valid_product_id(integration_value) OR  ource_value NOT IN('aw ','kubernete ','github','okta') OR generation_value<1 OR ver ion_value !~ '^[a-z][a-z0-9_.-]{1,63}$' OR length(worker_value) NOT BETWEEN 1 AND 128 OR length(lea e_token_value) NOT BETWEEN 16 AND 128 OR octet_length(input_dige t_value)<>32 OR j onb_typeof(item _value)<>'array' OR j onb_array_length(item _value)>4000 OR octet_length(item _value::text)>67108864 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid ri k projection input';END IF;
 IF EXISTS(
   SELECT 1 FROM j onb_array_element (item _value) item
   WHERE j onb_typeof(item)<>'object' OR (SELECT count(*) FROM j onb_object_key (item))<>3 OR item->>' ection' NOT IN('entitie ','relation hip ','evidence') OR NOT za p_valid_product_id(item->>'id') OR j onb_typeof(item->'payload')<>'object' OR octet_length((item->'payload')::text)>1048576 OR item->'payload'->>'id' IS DISTINCT FROM item->>'id'
 ) OR EXISTS(SELECT 1 FROM j onb_array_element (item _value) item GROUP BY item->>' ection',item->>'id' HAVING count(*)>1) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid ri k projection item';END IF;
 SELECT COALESCE(j onb_agg(j onb_build_object(' ection',item->>' ection','id',item->>'id','payload',item->'payload') ORDER BY item->>' ection',item->>'id'),'[]'::j onb),count(*)::integer INTO canonical_item ,item_count_value FROM j onb_array_element (item _value) item;
 content_dige t_value:=dige t(convert_to(canonical_item ::text,'UTF8'),' ha256');
 SELECT * INTO input_row FROM za p_di covery_ nap hot_input  WHERE (organization_id,work pace_id,environment_id, nap hot_id)=(organization_value,work pace_value,environment_value, nap hot_value) FOR SHARE;
 IF NOT FOUND OR (input_row.integration_id,input_row. ource,input_row.generation,input_row.candidate_dige t) IS DISTINCT FROM (integration_value, ource_value,generation_value,input_dige t_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='ri k projection  nap hot input conflict';END IF;
 SELECT COALESCE(j onb_agg(j onb_build_object(' ection', ection,'id',item_id,'payload',payload) ORDER BY  ection,item_id),'[]'::j onb) INTO expected_item  FROM za p_di covery_ nap hot_projection_item  WHERE (organization_id,work pace_id,environment_id, nap hot_id)=(organization_value,work pace_value,environment_value, nap hot_value);
 IF canonical_item  IS DISTINCT FROM expected_item  THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='ri k projection item  et conflict';END IF;
 PERFORM 1 FROM za p_projection_work WHERE (organization_id,work pace_id,environment_id, nap hot_id,kind,ver ion, tate,lea e_owner,lea e_token,input_dige t)=(organization_value,work pace_value,environment_value, nap hot_value,'ri k',ver ion_value,'lea ed',worker_value,lea e_token_value,input_dige t_value) AND lea e_expire _at>tran action_time tamp() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='ri k projection lea e mi ing';END IF;
 PERFORM pg_advi ory_xact_lock(ha htextextended(j onb_build_array(organization_value,work pace_value,environment_value,integration_value, ource_value)::text,13));
 SELECT * INTO current_row FROM za p_di covery_ri k_projection_current WHERE (organization_id,work pace_id,environment_id,integration_id, ource)=(organization_value,work pace_value,environment_value,integration_value, ource_value) FOR UPDATE;
 IF FOUND AND current_row.generation>generation_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE=' tale ri k projection input';END IF;
 IF FOUND AND current_row.generation=generation_value THEN
   SELECT COALESCE(j onb_agg(j onb_build_object(' ection', ection,'id',item_id,'payload',payload) ORDER BY  ection,item_id),'[]'::j onb) INTO  tored_item  FROM za p_di covery_ri k_projection_item  WHERE (organization_id,work pace_id,environment_id,integration_id, ource)=(organization_value,work pace_value,environment_value,integration_value, ource_value);
   IF (current_row. nap hot_id,current_row.input_dige t,current_row.content_dige t,current_row.item_count) IS DISTINCT FROM ( nap hot_value,input_dige t_value,content_dige t_value,item_count_value) OR  tored_item  IS DISTINCT FROM canonical_item  THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='ri k projection input drift';END IF;
   replayed_value:=true;
 ELSE
   DELETE FROM za p_di covery_ri k_projection_item  WHERE (organization_id,work pace_id,environment_id,integration_id, ource)=(organization_value,work pace_value,environment_value,integration_value, ource_value);
   INSERT INTO za p_di covery_ri k_projection_current(organization_id,work pace_id,environment_id,integration_id, ource, nap hot_id,generation,input_dige t,content_dige t,item_count)
   VALUES(organization_value,work pace_value,environment_value,integration_value, ource_value, nap hot_value,generation_value,input_dige t_value,content_dige t_value,item_count_value)
   ON CONFLICT(organization_id,work pace_id,environment_id,integration_id, ource) DO UPDATE SET  nap hot_id=excluded. nap hot_id,generation=excluded.generation,input_dige t=excluded.input_dige t,content_dige t=excluded.content_dige t,item_count=excluded.item_count,updated_at=tran action_time tamp();
   INSERT INTO za p_di covery_ri k_projection_item (organization_id,work pace_id,environment_id,integration_id, ource, nap hot_id,generation,input_dige t,content_dige t, ection,item_id,payload)
   SELECT organization_value,work pace_value,environment_value,integration_value, ource_value, nap hot_value,generation_value,input_dige t_value,content_dige t_value,item->>' ection',item->>'id',item->'payload' FROM j onb_array_element (canonical_item ) item;

   WITH ranked_finding  AS (
    SELECT item.payload->>'finding_id' finding_id,item.payload->>'entity_id' entity_id,item.payload->>'check_id' check_id,item.payload->>'id' evidence_id,item. ource,
      row_number() OVER(PARTITION BY item.payload->>'finding_id' ORDER BY item.integration_id,item. ource,item.item_id) rank_value
    FROM za p_di covery_ri k_projection_item  item
    WHERE (item.organization_id,item.work pace_id,item.environment_id,item. ection)=(organization_value,work pace_value,environment_value,'evidence')
      AND item.payload ?& ARRAY['finding_id','entity_id','check_id',' everity',' tatu '] AND item.payload->>' everity'='high' AND item.payload->>' tatu '='FAIL'
      AND za p_valid_product_id(item.payload->>'finding_id') AND za p_valid_product_id(item.payload->>'entity_id') AND za p_valid_product_id(item.payload->>'id') AND item.payload->>'check_id' ~ '^[a-z][a-z0-9_]{0,63}$'
   )
   SELECT COALESCE(j onb_agg(j onb_build_object('finding_id',finding_id,'entity_id',entity_id,'check_id',check_id,'evidence_id',evidence_id,' ource', ource) ORDER BY finding_id),'[]'::j onb) INTO finding_item  FROM ranked_finding  WHERE rank_value=1;
   PERFORM za p_inventory_apply_finding (organization_value,work pace_value,environment_value,finding_item );
   PERFORM za p_inventory_refre h_po ture_finding (organization_value,work pace_value,environment_value);
 END IF;
 RETURN j onb_build_object(' nap hot_id', nap hot_value,'integration_id',integration_value,' ource', ource_value,'generation',generation_value,'input_dige t',encode(input_dige t_value,'ba e64'),'content_dige t',encode(content_dige t_value,'ba e64'),'driver_receipt','po tgre :ri k-input:'|| nap hot_value||': ha256:'||encode(content_dige t_value,'hex'),'replayed',replayed_value);
END

