DECLARE candidate_item  j onb;active_count integer;re olved_count integer;
BEGIN
 IF NOT za p_valid_product_id(organization_value) OR NOT za p_valid_product_id(work pace_value) OR NOT za p_valid_product_id(environment_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid po ture  cope';END IF;
 PERFORM pg_advi ory_xact_lock(ha htextextended(concat_w (chr(31),'za p-po ture',organization_value,work pace_value,environment_value),0));
 WITH agent  AS (
  SELECT entity_value.id,entity_value. tate,entity_value.winning_evidence_id,entity_value.winning_attribute ->'po ture' po ture,COALESCE(annotation.owner_value,'') owner_value
  FROM za p_inventory_entitie  entity_value LEFT JOIN za p_inventory_annotation  annotation
   ON (annotation.organization_id,annotation.work pace_id,annotation.environment_id,annotation.entity_id)=(entity_value.organization_id,entity_value.work pace_id,entity_value.environment_id,entity_value.id)
  WHERE (entity_value.organization_id,entity_value.work pace_id,entity_value.environment_id,entity_value.product_kind)=(organization_value,work pace_value,environment_value,'agent')
   AND entity_value.winning_evidence_id IS NOT NULL
 ),matche  AS (
  SELECT agent.id agent_id,agent.winning_evidence_id evidence_id,rule_value.rule,rule_value.title
  FROM agent  agent CROSS JOIN LATERAL (VALUES
   ('ownerle _agent','Agent ha  no owner',agent. tate='active' AND agent.owner_value=''),
   ('human_credential','Agent u e  a human credential',agent. tate='active' AND (agent.po ture->>'human_credential')::boolean),
   (' hared_credential','Credential i   hared acro  agent ',agent. tate='active' AND agent.po ture->>'credential_fingerprint' ~ '^ ha256:[0-9a-f]{64}$' AND (SELECT count(*) FROM agent   hared WHERE  hared. tate='active' AND ( hared.po ture->>'credential_active')::boolean AND  hared.po ture->>'credential_fingerprint'=agent.po ture->>'credential_fingerprint')>1),
   ('untru ted_production_write','Untru ted input can write to production',agent. tate='active' AND (agent.po ture->>'untru ted_input')::boolean AND (agent.po ture->>'production_write')::boolean),
   (' hell_credential','Shell execution can u e a production credential',agent. tate='active' AND (agent.po ture->>' hell_execution')::boolean AND (agent.po ture->>'production_credential')::boolean),
   ('egre _ en itive','Unre tricted egre  can reach  en itive data',agent. tate='active' AND (agent.po ture->>'unre tricted_egre ')::boolean AND (agent.po ture->>' en itive_data_reach')::boolean),
   ('unapproved_tool','Agent can reach an unapproved remote tool',agent. tate='active' AND (agent.po ture->>'unapproved_remote_tool')::boolean),
   ('de tructive_no_control','De tructive action lack  runtime control',agent. tate='active' AND (agent.po ture->>'de tructive_tool')::boolean AND NOT (agent.po ture->>'runtime_control')::boolean),
   ('no_runtime_coverage','Production agent lack  runtime policy coverage',agent. tate='active' AND (agent.po ture->>'production_agent')::boolean AND NOT (agent.po ture->>'runtime_policy_ upported')::boolean),
   ('weak_runtime_i olation','Runtime ha  weak i olation',agent. tate='active' AND ((agent.po ture->>'ho t_file y tem')::boolean OR (agent.po ture->>'privileged')::boolean)),
   ('cicd_production_ ecret','CI/CD write can reach production  ecret ',agent. tate='active' AND (agent.po ture->>'cicd_write')::boolean AND (agent.po ture->>'production_ ecret_reach')::boolean),
   ('zombie_credential','Inactive agent retain  an active credential',agent. tate='tomb toned' AND (agent.po ture->>'credential_active')::boolean)
  ) rule_value(rule,title,matched)
  WHERE rule_value.matched
 ),candidate  AS (
  SELECT za p_di covery_canonical_id(organization_value,work pace_value,environment_value,'po ture_finding',matche .agent_id||chr(31)||matche .rule) finding_id,* FROM matche 
 )
 SELECT COALESCE(j onb_agg(j onb_build_object('finding_id',finding_id,'agent_id',agent_id,'evidence_id',evidence_id,'rule',rule,'title',title) ORDER BY finding_id),'[]'::j onb) INTO candidate_item  FROM candidate ;
 IF EXISTS(
  SELECT 1 FROM j onb_array_element (candidate_item ) candidate JOIN za p_ri k_finding  finding
   ON (finding.organization_id,finding.work pace_id,finding.environment_id,finding.id)=(organization_value,work pace_value,environment_value,candidate->>'finding_id')
  WHERE (finding. ource,finding.rule,finding.compliance_context) IS DISTINCT FROM ('po ture',candidate->>'rule','za p-po ture:'||(candidate->>'rule'))
 ) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='po ture finding owner hip conflict';END IF;

 INSERT INTO za p_ri k_finding  AS finding(organization_id,work pace_id,environment_id,id, ource,rule,title, everity, tatu ,agent_id,compliance_context)
 SELECT organization_value,work pace_value,environment_value,candidate->>'finding_id','po ture',candidate->>'rule',candidate->>'title','high','open',candidate->>'agent_id','za p-po ture:'||(candidate->>'rule') FROM j onb_array_element (candidate_item ) candidate
 ON CONFLICT(organization_id,work pace_id,environment_id,id) DO UPDATE SET
   ource='po ture',rule=excluded.rule,title=excluded.title, everity='high', tatu =CASE WHEN finding. tatu  IN('accepted','under_review') THEN finding. tatu  ELSE 'open' END,
  agent_id=excluded.agent_id,path_id=NULL,compliance_context=excluded.compliance_context,acceptance_rea on=CASE WHEN finding. tatu ='accepted' THEN finding.acceptance_rea on ELSE NULL END,
  ver ion=finding.ver ion+CASE WHEN (finding. ource,finding.rule,finding.title,finding. everity,finding. tatu ,finding.agent_id,finding.path_id,finding.compliance_context,finding.acceptance_rea on) IS DISTINCT FROM ('po ture',excluded.rule,excluded.title,'high',CASE WHEN finding. tatu  IN('accepted','under_review') THEN finding. tatu  ELSE 'open' END,excluded.agent_id,NULL,excluded.compliance_context,CASE WHEN finding. tatu ='accepted' THEN finding.acceptance_rea on ELSE NULL END) THEN 1 ELSE 0 END,
  updated_at=CASE WHEN (finding. ource,finding.rule,finding.title,finding. everity,finding. tatu ,finding.agent_id,finding.path_id,finding.compliance_context,finding.acceptance_rea on) IS DISTINCT FROM ('po ture',excluded.rule,excluded.title,'high',CASE WHEN finding. tatu  IN('accepted','under_review') THEN finding. tatu  ELSE 'open' END,excluded.agent_id,NULL,excluded.compliance_context,CASE WHEN finding. tatu ='accepted' THEN finding.acceptance_rea on ELSE NULL END) THEN tran action_time tamp() ELSE finding.updated_at END;

 DELETE FROM za p_ri k_finding_evidence evidence_value USING j onb_array_element (candidate_item ) candidate
 WHERE (evidence_value.organization_id,evidence_value.work pace_id,evidence_value.environment_id,evidence_value.finding_id)=(organization_value,work pace_value,environment_value,candidate->>'finding_id');
 INSERT INTO za p_ri k_finding_evidence(organization_id,work pace_id,environment_id,finding_id,po ition,evidence_id)
 SELECT organization_value,work pace_value,environment_value,candidate->>'finding_id',1,candidate->>'evidence_id' FROM j onb_array_element (candidate_item ) candidate;

 DELETE FROM za p_ri k_finding_factor  factor_value USING j onb_array_element (candidate_item ) candidate
 WHERE (factor_value.organization_id,factor_value.work pace_id,factor_value.environment_id,factor_value.finding_id)=(organization_value,work pace_value,environment_value,candidate->>'finding_id');
 INSERT INTO za p_ri k_finding_factor (organization_id,work pace_id,environment_id,finding_id,po ition,name,evidence_id)
 SELECT organization_value,work pace_value,environment_value,candidate->>'finding_id',1,candidate->>'title',candidate->>'evidence_id' FROM j onb_array_element (candidate_item ) candidate;

 UPDATE za p_ri k_finding  finding SET  tatu ='re olved',path_id=NULL,acceptance_rea on=NULL,ver ion=finding.ver ion+1,updated_at=tran action_time tamp()
 WHERE (finding.organization_id,finding.work pace_id,finding.environment_id,finding. ource)=(organization_value,work pace_value,environment_value,'po ture')
  AND finding.compliance_context LIKE 'za p-po ture:%' AND finding. tatu  IN('open','under_review')
  AND NOT EXISTS(SELECT 1 FROM j onb_array_element (candidate_item ) candidate WHERE candidate->>'finding_id'=finding.id);
 GET DIAGNOSTICS re olved_count=ROW_COUNT;
 SELECT count(*) INTO active_count FROM za p_ri k_finding  finding WHERE (finding.organization_id,finding.work pace_id,finding.environment_id,finding. ource)=(organization_value,work pace_value,environment_value,'po ture') AND finding.compliance_context LIKE 'za p-po ture:%' AND finding. tatu  IN('open','under_review','accepted');
 RETURN j onb_build_object('active_count',active_count,'re olved_count',re olved_count);
END

DECLARE operation_value text:=CASE WHEN TG_OP='DELETE' THEN OLD.operation ELSE NEW.operation END;organization_value text:=CASE WHEN TG_OP='DELETE' THEN OLD.organization_id ELSE NEW.organization_id END;work pace_value text:=CASE WHEN TG_OP='DELETE' THEN OLD.work pace_id ELSE NEW.work pace_id END;environment_value text:=CASE WHEN TG_OP='DELETE' THEN OLD.environment_id ELSE NEW.environment_id END;
BEGIN
 IF operation_value IN('home','agent ','tool ','identitie ','runtime ') OR operation_value ~ '^(agent|tool|identity|runtime|a et):pid_[0-9a-f-]{36}$' OR operation_value ~ '^agent_(capabilitie |relation hip | e ion ):pid_[0-9a-f-]{36}$' THEN
  PERFORM pg_advi ory_xact_lock(ha htextextended(concat_w (chr(31),'za p-inventory-cutover',organization_value,work pace_value,environment_value),0));
  IF za p_inventory_ cope_ tate(organization_value,work pace_value,environment_value)->>'pha e'='cutover' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='typed inventory cutover write fence';END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END

DECLARE current_dige t bytea;deleted_count integer;
BEGIN
 SELECT dige t(convert_to(COALESCE(j onb_object_agg(payload.operation,payload.payload ORDER BY payload.operation),'{}'::j onb)::text,'UTF8'),' ha256') INTO current_dige t FROM za p_core_payload  payload WHERE (payload.organization_id,payload.work pace_id,payload.environment_id)=(organization_value,work pace_value,environment_value) AND (payload.operation IN('home','agent ','tool ','identitie ','runtime ') OR payload.operation ~ '^(agent|tool|identity|runtime|a et):pid_[0-9a-f-]{36}$' OR payload.operation ~ '^agent_(capabilitie |relation hip | e ion ):pid_[0-9a-f-]{36}$');
 IF current_dige t<>expected_dige t THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='legacy inventory changed during cutover';END IF;
 DELETE FROM za p_core_payload  payload WHERE (payload.organization_id,payload.work pace_id,payload.environment_id)=(organization_value,work pace_value,environment_value) AND (payload.operation IN('home','agent ','tool ','identitie ','runtime ') OR payload.operation ~ '^(agent|tool|identity|runtime|a et):pid_[0-9a-f-]{36}$' OR payload.operation ~ '^agent_(capabilitie |relation hip | e ion ):pid_[0-9a-f-]{36}$');GET DIAGNOSTICS deleted_count=ROW_COUNT;RETURN deleted_count;
END

DECLARE
  agent_count_value bigint; high_ri k_value bigint; pending_approval_value bigint; olde t_approval_value bigint;
  need _human_value bigint; failed_value bigint; inconclu ive_value bigint; contained_value bigint; remediated_value bigint;
BEGIN
  IF za p_inventory_ cope_ tate(organization_value,work pace_value,environment_value)->>'pha e'<>'cutover' THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='typed inventory  cope unavailable';
  END IF;
  SELECT count(*) INTO agent_count_value FROM za p_inventory_entitie  entity_value WHERE (entity_value.organization_id,entity_value.work pace_id,entity_value.environment_id,entity_value. tate,entity_value.product_kind)=(organization_value,work pace_value,environment_value,'active','agent');
  SELECT count(*) INTO high_ri k_value FROM za p_ri k_attack_path  path_value WHERE (path_value.organization_id,path_value.work pace_id,path_value.environment_id)=(organization_value,work pace_value,environment_value) AND path_value. tate IN('ob erved','verified');
  SELECT count(*),COALESCE(floor(extract(epoch FROM tran action_time tamp()-min(approval.created_at)))::bigint,0)
    INTO pending_approval_value,olde t_approval_value
    FROM za p_ ecurity_agent_approval  approval
   WHERE approval.organization_id=organization_value AND approval.work pace_id=work pace_value AND approval.environment_id=environment_value AND approval. tate='pending';
  SELECT count(*) FILTER(WHERE run. tate='need _human'),count(*) FILTER(WHERE run. tate='failed'),count(*) FILTER(WHERE run. tate='inconclu ive'),
         count(*) FILTER(WHERE run. tate='contained' AND run.updated_at>=tran action_time tamp()-interval '24 hour '),count(*) FILTER(WHERE run. tate='remediated' AND run.updated_at>=tran action_time tamp()-interval '24 hour ')
    INTO need _human_value,failed_value,inconclu ive_value,contained_value,remediated_value
    FROM za p_ ecurity_agent_run  run
   WHERE run.organization_id=organization_value AND run.work pace_id=work pace_value AND run.environment_id=environment_value;
  RETURN j onb_build_object(
    'agent_count',agent_count_value,'high_ri k_path ',high_ri k_value,'verified_change ',0,'blocked_change ',0,
    'pending_approval ',pending_approval_value,'olde t_approval_age_ econd ',olde t_approval_value,
    'need _human_run ',need _human_value,'failed_run ',failed_value,'inconclu ive_run ',inconclu ive_value,
    'recent_contained',contained_value,'recent_remediated',remediated_value,
    'healthy',high_ri k_value=0 AND pending_approval_value=0 AND need _human_value=0 AND failed_value=0 AND inconclu ive_value=0,
    'attention_required',high_ri k_value>0 OR pending_approval_value>0 OR need _human_value>0 OR failed_value>0 OR inconclu ive_value>0);
END
